const newsData=[{id:"chung-chi-tieu-chuan-chat-luong-vaf",title:"Chứng Chỉ Và Tiêu Chuẩn Chất Lượng VAF – Nền Tảng Cho Giải Pháp Lọc Khí",seoTitle:"Chứng Chỉ VAF: ISO 9001, ISO 13485, EN 1822, ISO 16890",cat:"Chứng Chỉ",img:"images/anh-tin-tin/chung-chi-tieu-chuan-vaf-cover.webp",imgWidth:1200,imgHeight:675,author:"VAF Technical Team",date:"10/08/2026",desc:"Tìm hiểu chứng chỉ VAF và các tiêu chuẩn ISO 9001, ISO 13485, EN 1822, ISO 16890 áp dụng trong sản xuất lọc khí, HEPA và thiết bị phòng sạch.",faq:[{question:"VAF có chứng chỉ ISO 9001 không?",answer:"VAF công bố áp dụng hệ thống quản lý chất lượng theo ISO 9001:2015. Khách hàng nên đối chiếu bản chứng chỉ hiện hành để xác nhận phạm vi, tổ chức chứng nhận và thời hạn hiệu lực."},{question:"VAF có chứng chỉ ISO 13485 không?",answer:"VAF công bố chứng nhận ISO 13485:2016 liên quan đến hệ thống quản lý chất lượng trong phạm vi được ghi cụ thể trên chứng chỉ."},{question:"Lọc HEPA VAF được đánh giá theo tiêu chuẩn nào?",answer:"Các sản phẩm HEPA và ULPA của VAF được phát triển cho những ứng dụng sử dụng phương pháp thử và phân loại theo EN 1822. Tiêu chuẩn và hồ sơ thử nghiệm cần được xác nhận theo từng model, đơn hàng hoặc dự án."},{question:"ISO 16890 dùng cho loại lọc nào?",answer:"ISO 16890 chủ yếu dùng để đánh giá lọc khí thông gió theo hiệu suất đối với các nhóm hạt ePM1, ePM2.5, ePM10 và ISO Coarse."},{question:"Lọc HEPA có chứng nhận GMP không?",answer:"GMP là hệ thống nguyên tắc thực hành sản xuất tốt áp dụng cho cơ sở và toàn bộ quá trình sản xuất, không phải cấp hiệu suất hay chứng nhận riêng của một bộ lọc HEPA. HEPA là một thành phần của giải pháp HVAC và phòng sạch hỗ trợ cơ sở đáp ứng yêu cầu kiểm soát môi trường theo GMP."},{question:"Chứng chỉ ISO có thay thế Test Report của bộ lọc không?",answer:"Không. Chứng chỉ ISO xác nhận hệ thống quản lý trong một phạm vi cụ thể, còn Test Report ghi nhận kết quả thử nghiệm của mẫu hoặc sản phẩm theo phương pháp và điều kiện xác định."}],content:'\n            <nav aria-label="Mục lục bài viết" class="bg-slate-50 border border-slate-200 rounded-2xl p-6 mb-10">\n                <h2 class="text-xl font-bold text-secondary mb-4">Nội dung chính</h2>\n                <ol class="list-decimal pl-6 space-y-2">\n                    <li><a class="text-primary hover:underline" href="#vai-tro-tieu-chuan">Vai trò của chứng chỉ và tiêu chuẩn lọc khí</a></li>\n                    <li><a class="text-primary hover:underline" href="#iso-9001">ISO 9001:2015</a></li>\n                    <li><a class="text-primary hover:underline" href="#iso-13485">ISO 13485:2016</a></li>\n                    <li><a class="text-primary hover:underline" href="#en-1822">EN 1822 dành cho HEPA và ULPA</a></li>\n                    <li><a class="text-primary hover:underline" href="#iso-16890">ISO 16890 cho lọc khí thông gió</a></li>\n                    <li><a class="text-primary hover:underline" href="#gmp">GMP và kiểm soát môi trường dược phẩm</a></li>\n                    <li><a class="text-primary hover:underline" href="#kiem-soat-chat-luong">Kiểm soát chất lượng tại VAF</a></li>\n                    <li><a class="text-primary hover:underline" href="#phan-biet-ho-so">Phân biệt CO, CQ, COA và Test Report</a></li>\n                    <li><a class="text-primary hover:underline" href="#faq">Câu hỏi thường gặp</a></li>\n                </ol>\n            </nav>\n\n            <p class="mb-5 leading-8"><strong>Chứng chỉ VAF</strong> và các tiêu chuẩn kỹ thuật là một phần quan trọng trong quá trình kiểm soát chất lượng lọc khí, thiết bị phòng sạch. Với những môi trường yêu cầu nghiêm ngặt như điện tử, dược phẩm, thực phẩm, bệnh viện và nhà máy công nghiệp, chất lượng sản phẩm không thể chỉ được đánh giá qua hình thức bên ngoài hoặc thông số trên catalogue.</p>\n            <p class="mb-5 leading-8">Tại VAF – Viet Air Filter, hệ thống quản lý và các giải pháp lọc khí được phát triển dựa trên những tiêu chuẩn phù hợp như ISO 9001:2015, ISO 13485:2016, EN 1822 và ISO 16890. Đây là nền tảng để kiểm soát nguyên vật liệu, quá trình sản xuất, thử nghiệm, hoàn thiện và hồ sơ bàn giao.</p>\n\n            <aside class="bg-amber-50 border-l-4 border-amber-500 rounded-xl p-6 my-8 leading-8">\n                <strong>Lưu ý quan trọng:</strong> ISO 9001 và ISO 13485 là tiêu chuẩn về hệ thống quản lý chất lượng. EN 1822 và ISO 16890 là tiêu chuẩn kỹ thuật dùng để thử nghiệm hoặc phân loại các nhóm lọc khí. Chứng nhận hệ thống quản lý không thay thế báo cáo thử nghiệm của một sản phẩm cụ thể.\n            </aside>\n\n            <h2 id="vai-tro-tieu-chuan" class="text-3xl font-bold text-secondary mt-10 mb-6">Vì sao chứng chỉ và tiêu chuẩn quan trọng với lọc khí?</h2>\n            <p class="mb-5 leading-8">Hai bộ lọc có thể giống nhau về kích thước, vật liệu khung và hình thức nhưng khác biệt đáng kể về hiệu suất vận hành. Khi lựa chọn lọc cho HVAC hoặc phòng sạch, kỹ sư cần xem xét đồng thời nhiều yếu tố:</p>\n            <ul class="list-disc pl-6 space-y-3 mb-8">\n                <li>Hiệu suất giữ bụi theo từng nhóm kích thước hạt.</li>\n                <li>Hiệu suất tại MPPS đối với lọc HEPA và ULPA.</li>\n                <li>Chênh áp ban đầu và giới hạn chênh áp cuối.</li>\n                <li>Lưu lượng khí thiết kế và khả năng chứa bụi.</li>\n                <li>Độ đồng đều của vật liệu lọc và độ kín của sản phẩm.</li>\n                <li>Khả năng kiểm soát rò rỉ, truy xuất và duy trì chất lượng giữa các lô.</li>\n            </ul>\n            <p class="mb-5 leading-8">Áp dụng đúng tiêu chuẩn giúp tạo ra một phương pháp đánh giá có cơ sở và có thể kiểm chứng. Tuy nhiên, tiêu chuẩn phù hợp phải được lựa chọn theo loại sản phẩm và điều kiện vận hành, thay vì sử dụng một chứng chỉ chung để đại diện cho mọi đặc tính kỹ thuật.</p>\n\n            <h2 id="iso-9001" class="text-3xl font-bold text-secondary mt-10 mb-6">ISO 9001:2015 – Hệ thống quản lý chất lượng</h2>\n            <p class="mb-5 leading-8">ISO 9001:2015 là tiêu chuẩn hệ thống quản lý chất lượng được áp dụng rộng rãi. Đối với doanh nghiệp sản xuất lọc khí, tiêu chuẩn này không chỉ đề cập đến chất lượng một sản phẩm riêng lẻ mà hướng đến cách tổ chức kiểm soát toàn bộ quá trình.</p>\n            <div class="grid md:grid-cols-2 gap-5 my-8">\n                <div class="border rounded-xl p-5"><h3 class="text-xl font-bold text-secondary mb-2">Kiểm soát đầu vào</h3><p>Tiếp nhận yêu cầu khách hàng, đánh giá nhà cung cấp và kiểm soát nguyên vật liệu.</p></div>\n                <div class="border rounded-xl p-5"><h3 class="text-xl font-bold text-secondary mb-2">Quản lý sản xuất</h3><p>Chuẩn hóa công đoạn, tài liệu kỹ thuật và tiêu chí kiểm tra trong quá trình.</p></div>\n                <div class="border rounded-xl p-5"><h3 class="text-xl font-bold text-secondary mb-2">Kiểm tra thành phẩm</h3><p>Đánh giá ngoại quan, kích thước và các thông số kỹ thuật theo phạm vi áp dụng.</p></div>\n                <div class="border rounded-xl p-5"><h3 class="text-xl font-bold text-secondary mb-2">Truy xuất và cải tiến</h3><p>Quản lý hồ sơ, sản phẩm không phù hợp và hoạt động cải tiến quy trình.</p></div>\n            </div>\n            <figure class="my-10 max-w-3xl mx-auto">\n                <img src="images/chung-chi/iso9001.webp" alt="Chứng chỉ ISO 9001 2015 của VAF Viet Air Filter" width="1536" height="1090" loading="lazy" class="w-full h-auto rounded-xl shadow-lg">\n                <figcaption class="text-center text-sm text-slate-500 mt-3">Hình ảnh chứng chỉ ISO 9001:2015 được VAF công bố.</figcaption>\n            </figure>\n            <p class="mb-5 leading-8">Với khách hàng công nghiệp, giá trị thực tế nằm ở khả năng duy trì sự ổn định giữa nhiều lần đặt hàng: đúng kích thước, vật liệu, cấu tạo, hiệu suất, chênh áp và chất lượng hoàn thiện theo yêu cầu đã thống nhất.</p>\n\n            <h2 id="iso-13485" class="text-3xl font-bold text-secondary mt-10 mb-6">ISO 13485:2016 – Quản lý chất lượng liên quan đến thiết bị y tế</h2>\n            <p class="mb-5 leading-8">ISO 13485:2016 là tiêu chuẩn về hệ thống quản lý chất lượng dành cho các tổ chức hoạt động trong lĩnh vực thiết bị y tế và chuỗi cung ứng liên quan. Môi trường y tế và phòng sạch thường yêu cầu kiểm soát hồ sơ, truy xuất và tính nhất quán cao hơn hệ thống thông gió tiện nghi thông thường.</p>\n            <p class="mb-5 leading-8">Các khu vực có thể yêu cầu giải pháp kiểm soát không khí nghiêm ngặt gồm phòng mổ, phòng xét nghiệm, khu vực sạch trong bệnh viện, nhà máy dược phẩm, phòng nghiên cứu và hệ thống sử dụng HEPA terminal filter. Phạm vi áp dụng cụ thể luôn cần được đối chiếu trên chứng chỉ hiện hành.</p>\n            <figure class="my-10 max-w-3xl mx-auto">\n                <img src="images/chung-chi/iso13485.webp" alt="Chứng chỉ ISO 13485 2016 của VAF" width="1536" height="1090" loading="lazy" class="w-full h-auto rounded-xl shadow-lg">\n                <figcaption class="text-center text-sm text-slate-500 mt-3">Chứng chỉ ISO 13485:2016 trong hệ thống hồ sơ chất lượng VAF.</figcaption>\n            </figure>\n\n            <h2 id="en-1822" class="text-3xl font-bold text-secondary mt-10 mb-6">EN 1822 – Tiêu chuẩn dành cho lọc EPA, HEPA và ULPA</h2>\n            <p class="mb-5 leading-8">Khác với ISO 9001, EN 1822 liên quan trực tiếp đến việc thử nghiệm và phân loại lọc khí hiệu suất cao EPA, HEPA và ULPA. Tiêu chuẩn này có ý nghĩa với HEPA Filter, ULPA Filter, Mini-pleat HEPA, HEPA sử dụng trong FFU, HEPA Box và các thiết bị phòng sạch tích hợp cấp lọc cuối.</p>\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">MPPS là gì?</h3>\n            <p class="mb-5 leading-8"><strong>MPPS</strong> là viết tắt của Most Penetrating Particle Size, tức kích thước hạt có khả năng xuyên qua vật liệu lọc cao nhất trong điều kiện thử xác định. Phương pháp đánh giá theo EN 1822 xem xét hiệu suất tại vùng kích thước hạt khó lọc nhất, vì vậy hiệu suất tại MPPS là thông số quan trọng khi phân loại HEPA và ULPA.</p>\n            <div class="grid md:grid-cols-2 gap-6 my-8">\n                <div class="bg-primary/5 border border-primary/20 rounded-xl p-6"><h3 class="text-xl font-bold text-secondary mb-3">HEPA H13</h3><p>Được sử dụng trong nhiều hệ thống phòng sạch, bệnh viện, dược phẩm, điện tử và HVAC yêu cầu độ sạch cao.</p></div>\n                <div class="bg-primary/5 border border-primary/20 rounded-xl p-6"><h3 class="text-xl font-bold text-secondary mb-3">HEPA H14</h3><p>Có hiệu suất cao hơn H13, phù hợp với khu vực cần kiểm soát hạt nghiêm ngặt hơn khi hệ thống đáp ứng yêu cầu lưu lượng và chênh áp.</p></div>\n            </div>\n            <p class="mb-5 leading-8">Không nên mặc định cấp lọc càng cao thì càng phù hợp. Hiệu suất, chênh áp, công suất quạt và chi phí vận hành phải được đánh giá như một hệ thống hoàn chỉnh. Xem thêm bài <a class="text-primary font-semibold hover:underline" href="/news/hepa-filter-la-gi" onclick="openNewsDetail(\'hepa-filter-la-gi\'); return false;">HEPA Filter là gì</a>.</p>\n            <figure class="my-10 max-w-3xl mx-auto">\n                <img src="images/anh-tulieu/dop-test.webp" alt="Kiểm tra độ kín và rò rỉ lọc HEPA tại VAF" width="1920" height="1280" loading="lazy" class="w-full h-auto rounded-xl shadow-lg">\n                <figcaption class="text-center text-sm text-slate-500 mt-3">Hoạt động kiểm tra lọc khí tại VAF.</figcaption>\n            </figure>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Vì sao cần kiểm tra rò rỉ lọc HEPA?</h3>\n            <p class="mb-5 leading-8">Hiệu suất của media chưa phải yếu tố duy nhất quyết định chất lượng bộ lọc hoàn chỉnh. Rò rỉ có thể xuất hiện trên media, tại điểm nối nếp gấp, vị trí tiếp giáp giữa media và khung, lớp keo làm kín hoặc điểm hư hỏng do vận chuyển. Với ứng dụng phù hợp, phương pháp aerosol như PAO có thể được dùng để đánh giá tính toàn vẹn và phát hiện vị trí rò rỉ.</p>\n\n            <h2 id="iso-16890" class="text-3xl font-bold text-secondary mt-10 mb-6">ISO 16890 – Tiêu chuẩn cho lọc khí thông gió</h2>\n            <p class="mb-5 leading-8">ISO 16890 đánh giá lọc khí thông gió dựa trên hiệu suất đối với các nhóm hạt <strong>ePM1, ePM2.5, ePM10 và ISO Coarse</strong>. Cách tiếp cận này phản ánh gần hơn đặc điểm bụi trong môi trường thực tế, nơi các hạt tồn tại ở nhiều kích thước khác nhau.</p>\n            <p class="mb-5 leading-8">Tiêu chuẩn có ý nghĩa đối với AHU, HVAC, MAU, hệ thống cấp khí tươi, nhà máy sản xuất, tòa nhà thương mại, trung tâm dữ liệu và các cơ sở thực phẩm, điện tử. Các dòng <a class="text-primary font-semibold hover:underline" href="/news/bag-filter-la-gi" onclick="openNewsDetail(\'bag-filter-la-gi\'); return false;">Bag Filter</a>, Pre Filter, Fine Filter và V-Bank Filter cần được lựa chọn dựa trên hiệu suất, lưu lượng, chênh áp và yêu cầu chất lượng không khí.</p>\n            <figure class="my-10 max-w-3xl mx-auto">\n                <img src="images/chung-chi/16890.webp" alt="Tiêu chuẩn ISO 16890 cho lọc khí thông gió VAF" width="1536" height="1090" loading="lazy" class="w-full h-auto rounded-xl shadow-lg">\n                <figcaption class="text-center text-sm text-slate-500 mt-3">Tài liệu ISO 16890 được giới thiệu trong khu vực chứng chỉ chất lượng VAF.</figcaption>\n            </figure>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">EN 779 và ISO 16890 có giống nhau không?</h3>\n            <p class="mb-5 leading-8">Không. EN 779 là hệ thống phân loại cũ với các cấp quen thuộc G3, G4, M5, M6, F7, F8 và F9. ISO 16890 sử dụng phương pháp đánh giá theo các nhóm hạt PM. Vì vậy, không nên chuyển đổi giữa hai hệ thống chỉ bằng một bảng tương đương đơn giản mà bỏ qua hiệu suất yêu cầu, lưu lượng, chênh áp, kích thước và điều kiện vận hành.</p>\n\n            <h2 id="gmp" class="text-3xl font-bold text-secondary mt-10 mb-6">GMP – Kiểm soát môi trường trong sản xuất dược phẩm</h2>\n            <p class="mb-5 leading-8"><strong>GMP</strong> (Good Manufacturing Practice – Thực hành tốt sản xuất) là hệ thống nguyên tắc nhằm bảo đảm sản phẩm được sản xuất và kiểm soát nhất quán trong những điều kiện phù hợp. Trong ngành dược phẩm, HVAC, lọc khí và phòng sạch là các thành phần quan trọng của giải pháp kiểm soát môi trường.</p>\n            <p class="mb-5 leading-8">Tùy sản phẩm, quy trình và cấp độ sạch, thiết kế môi trường có thể cần kiểm soát:</p>\n            <ul class="list-disc pl-6 space-y-3 mb-8">\n                <li>Nồng độ hạt trong không khí và cấp độ sạch của khu vực.</li>\n                <li>Hướng dòng khí và số lần trao đổi không khí.</li>\n                <li>Chênh áp giữa các phòng hoặc các vùng chức năng.</li>\n                <li>Nhiệt độ, độ ẩm và điều kiện tiện nghi của quá trình.</li>\n                <li>Nguy cơ nhiễm chéo và khả năng kiểm soát vi sinh.</li>\n                <li>Hoạt động giám sát, thẩm định và bảo trì hệ thống.</li>\n            </ul>\n            <div class="bg-primary/5 border-l-4 border-primary rounded-xl p-6 my-8 leading-8">\n                <strong>Cần hiểu đúng:</strong> GMP không phải cấp lọc và cũng không phải chứng nhận riêng dành cho một bộ lọc HEPA. Một bộ lọc HEPA đạt yêu cầu kỹ thuật chỉ là một thành phần trong hệ thống. Khả năng đáp ứng GMP phụ thuộc vào thiết kế tổng thể, phân vùng, HVAC, vận hành, thẩm định, giám sát và hệ thống quản lý chất lượng của cơ sở.\n            </div>\n            <p class="mb-5 leading-8">Các sản phẩm như HEPA Filter, HEPA Box, Fan Filter Unit (FFU), Air Shower, Pass Box và Laminar Air Flow có thể được tích hợp vào giải pháp phòng sạch dược phẩm. Việc lựa chọn phải dựa trên yêu cầu của khu vực, đánh giá rủi ro và hồ sơ thiết kế thay vì chỉ dựa vào tên thiết bị.</p>\n            <figure class="my-10 max-w-3xl mx-auto">\n                <img src="images/chung-chi/GMP.webp" alt="GMP và giải pháp kiểm soát môi trường phòng sạch dược phẩm VAF" width="990" height="1408" loading="lazy" class="w-full h-auto rounded-xl shadow-lg">\n                <figcaption class="text-center text-sm text-slate-500 mt-3">GMP liên quan đến toàn bộ hệ thống sản xuất và kiểm soát môi trường, không phải chứng nhận riêng của bộ lọc.</figcaption>\n            </figure>\n\n            <h2 id="kiem-soat-chat-luong" class="text-3xl font-bold text-secondary mt-10 mb-6">Từ tiêu chuẩn đến kiểm soát chất lượng thực tế tại VAF</h2>\n            <p class="mb-5 leading-8">Chứng chỉ chỉ thực sự có ý nghĩa khi các nguyên tắc quản lý được chuyển thành hoạt động kiểm soát trong sản xuất. Tùy từng sản phẩm và phạm vi kỹ thuật, quy trình có thể gồm:</p>\n            <ol class="list-decimal pl-6 space-y-4 mb-8">\n                <li><strong>Kiểm soát nguyên vật liệu:</strong> media, khung nhôm hoặc GI, keo sealant, gasket, lưới bảo vệ, separator và vật liệu túi.</li>\n                <li><strong>Kiểm soát quá trình:</strong> kích thước, số lượng và khoảng cách nếp gấp, độ chắc chắn của khung, độ kín và chất lượng liên kết.</li>\n                <li><strong>Kiểm tra thành phẩm:</strong> ngoại quan, kích thước, lưu lượng, chênh áp, hiệu suất và kiểm tra rò rỉ khi áp dụng.</li>\n                <li><strong>Quản lý hồ sơ:</strong> ghi nhận kết quả, nhận diện sản phẩm và duy trì thông tin truy xuất theo yêu cầu.</li>\n            </ol>\n            <figure class="my-10 max-w-4xl mx-auto">\n                <img src="images/anh-tulieu/Nhamayfront.webp" alt="Nhà máy sản xuất lọc khí VAF Viet Air Filter" width="1920" height="1080" loading="lazy" class="w-full h-auto rounded-xl shadow-lg">\n                <figcaption class="text-center text-sm text-slate-500 mt-3">Hình ảnh nhà máy VAF – Viet Air Filter.</figcaption>\n            </figure>\n\n            <h2 id="phan-biet-ho-so" class="text-3xl font-bold text-secondary mt-10 mb-6">CO, CQ, COA và Test Report khác chứng chỉ ISO thế nào?</h2>\n            <div class="overflow-x-auto my-8">\n                <table class="w-full border-collapse text-left">\n                    <thead><tr class="bg-secondary text-white"><th class="p-4">Tài liệu</th><th class="p-4">Ý nghĩa chính</th></tr></thead>\n                    <tbody>\n                        <tr class="border-b"><td class="p-4 font-bold">CO</td><td class="p-4">Certificate of Origin – tài liệu về xuất xứ hàng hóa trong trường hợp áp dụng.</td></tr>\n                        <tr class="border-b bg-slate-50"><td class="p-4 font-bold">CQ</td><td class="p-4">Certificate of Quality – xác nhận chất lượng hoặc sự phù hợp trong phạm vi công bố.</td></tr>\n                        <tr class="border-b"><td class="p-4 font-bold">COA</td><td class="p-4">Certificate of Analysis – ghi nhận kết quả phân tích hoặc kiểm tra sản phẩm, lô sản phẩm.</td></tr>\n                        <tr class="border-b bg-slate-50"><td class="p-4 font-bold">Test Report</td><td class="p-4">Báo cáo kết quả thử nghiệm theo phương pháp, thiết bị và điều kiện cụ thể.</td></tr>\n                        <tr class="border-b"><td class="p-4 font-bold">ISO Certificate</td><td class="p-4">Chứng nhận hệ thống quản lý đáp ứng phạm vi của tiêu chuẩn tương ứng.</td></tr>\n                    </tbody>\n                </table>\n            </div>\n            <p class="mb-5 leading-8">Ví dụ, ISO 9001:2015 phản ánh hệ thống quản lý chất lượng, trong khi Test Report theo EN 1822 có thể phản ánh kết quả thử hoặc phân loại của một mẫu lọc HEPA cụ thể. Bộ phận kỹ thuật, mua hàng và QA/QC cần xác định chính xác loại hồ sơ phải cung cấp ngay từ giai đoạn báo giá.</p>\n\n            <h2 class="text-3xl font-bold text-secondary mt-10 mb-6">Giải pháp lọc khí VAF phục vụ những lĩnh vực nào?</h2>\n            <p class="mb-5 leading-8">Hệ thống quản lý chất lượng và tiêu chuẩn kỹ thuật đặc biệt quan trọng với các ngành điện tử, bán dẫn, dược phẩm, bệnh viện, thực phẩm, đồ uống, nhà máy công nghiệp, tòa nhà thương mại và trung tâm dữ liệu.</p>\n            <p class="mb-5 leading-8">Danh mục giải pháp VAF gồm Pre Filter, Pleated Filter, Bag Filter, Fine Filter, V-Bank Filter, HEPA/ULPA Filter, Chemical Filter, FFU, HEPA Box, Air Shower, Pass Box, Laminar Air Flow và nhiều thiết bị phòng sạch khác. Xem <a class="text-primary font-semibold hover:underline" href="/products" onclick="handleNav(\'products\'); return false;">danh mục sản phẩm lọc khí VAF</a> hoặc <a class="text-primary font-semibold hover:underline" href="/projects" onclick="handleNav(\'projects\'); return false;">các dự án tiêu biểu</a>.</p>\n\n            <h2 id="faq" class="text-3xl font-bold text-secondary mt-10 mb-6">Câu hỏi thường gặp về chứng chỉ VAF</h2>\n            <div class="space-y-5 mb-10">\n                <section class="border rounded-xl p-6"><h3 class="text-xl font-bold text-secondary mb-3">VAF có chứng chỉ ISO 9001 không?</h3><p>VAF công bố áp dụng hệ thống quản lý chất lượng theo ISO 9001:2015. Khách hàng nên đối chiếu bản chứng chỉ hiện hành để xác nhận phạm vi, tổ chức chứng nhận và thời hạn hiệu lực.</p></section>\n                <section class="border rounded-xl p-6"><h3 class="text-xl font-bold text-secondary mb-3">VAF có chứng chỉ ISO 13485 không?</h3><p>VAF công bố chứng nhận ISO 13485:2016 liên quan đến hệ thống quản lý chất lượng trong phạm vi được ghi cụ thể trên chứng chỉ.</p></section>\n                <section class="border rounded-xl p-6"><h3 class="text-xl font-bold text-secondary mb-3">Lọc HEPA VAF được đánh giá theo tiêu chuẩn nào?</h3><p>Các sản phẩm HEPA và ULPA được phát triển cho ứng dụng sử dụng phương pháp thử, phân loại theo EN 1822. Hồ sơ cụ thể cần được xác nhận theo từng model hoặc dự án.</p></section>\n                <section class="border rounded-xl p-6"><h3 class="text-xl font-bold text-secondary mb-3">Lọc HEPA có chứng nhận GMP không?</h3><p>Không nên mô tả một bộ lọc riêng lẻ là “được chứng nhận GMP”. GMP áp dụng cho cơ sở và toàn bộ quá trình sản xuất; HEPA là một thành phần hỗ trợ hệ thống HVAC và phòng sạch kiểm soát môi trường theo yêu cầu thiết kế.</p></section>\n                <section class="border rounded-xl p-6"><h3 class="text-xl font-bold text-secondary mb-3">Có thể yêu cầu hồ sơ kỹ thuật khi mua lọc không?</h3><p>Tùy sản phẩm và phạm vi cung cấp, khách hàng có thể trao đổi trước với VAF về catalogue, thông số kỹ thuật, chứng chỉ, CO, CQ, COA hoặc báo cáo thử nghiệm cần thiết cho quá trình nghiệm thu.</p></section>\n            </div>\n\n            <section class="bg-secondary text-white rounded-2xl p-8 my-10">\n                <h2 class="text-3xl font-bold mb-4">Lựa chọn giải pháp lọc khí phù hợp cùng VAF</h2>\n                <p class="leading-8 mb-5">Mỗi hệ thống HVAC và phòng sạch có yêu cầu riêng về hiệu suất, lưu lượng, chênh áp, kích thước, vật liệu và điều kiện môi trường. Đội ngũ VAF hỗ trợ đánh giá các thông số này để lựa chọn giải pháp phù hợp và xác định hồ sơ kỹ thuật cần thiết.</p>\n                <p class="font-semibold">VAF – Viet Air Filter · Hotline: 1900 8949 · Website: vietfil.com</p>\n            </section>\n        '},{id:"bag-filter-la-gi",title:"Bag Filter Là Gì? Cấu Tạo, Phân Loại Và Cách Lựa Chọn",seoTitle:"Bag Filter Là Gì? Cấu Tạo, Phân Loại M5–F9",cat:"Kiến Thức",img:"images/san-pham/vpf7.webp",imgWidth:2400,imgHeight:1792,author:"VAF Technical Team",date:"30/07/2026",desc:"Bag Filter là gì? Tìm hiểu cấu tạo, nguyên lý, cấp M5, M6, F7–F9, ISO 16890, ứng dụng, cách chọn và thời điểm thay lọc túi HVAC.",faq:[{question:"Bag Filter có giặt và tái sử dụng được không?",answer:"Phần lớn Bag Filter dùng trong HVAC không được thiết kế để giặt. Việc giặt có thể làm biến dạng vật liệu, suy giảm hiệu suất và gây rò lọt khí. Chỉ vệ sinh hoặc tái sử dụng khi tài liệu kỹ thuật của nhà sản xuất cho phép."},{question:"Bao lâu nên thay Bag Filter?",answer:"Không có một chu kỳ cố định cho mọi hệ thống. Nên quyết định dựa trên chênh áp, lưu lượng gió, mức độ ô nhiễm và giới hạn do nhà sản xuất hoặc thiết kế HVAC quy định."},{question:"Bag Filter có thay thế HEPA Filter được không?",answer:"Không. Bag Filter thường là cấp lọc trung gian để giữ bụi mịn và giảm tải cho HEPA; HEPA vẫn là cấp lọc cuối trong các khu vực yêu cầu độ sạch cao."},{question:"VAF có sản xuất Bag Filter theo kích thước yêu cầu không?",answer:"Có. VAF có thể tư vấn cấp lọc, vật liệu, số túi, kích thước và khung theo lưu lượng gió, không gian lắp đặt và yêu cầu kỹ thuật của hệ thống."}],content:'\n            <nav aria-label="Mục lục bài viết" class="bg-slate-50 border border-slate-200 rounded-2xl p-6 mb-10">\n                <h2 class="text-xl font-bold text-secondary mb-4">Nội dung chính</h2>\n                <ol class="list-decimal pl-6 space-y-2">\n                    <li><a class="text-primary hover:underline" href="#bag-filter-la-gi">Bag Filter là gì?</a></li>\n                    <li><a class="text-primary hover:underline" href="#cau-tao">Cấu tạo và nguyên lý hoạt động</a></li>\n                    <li><a class="text-primary hover:underline" href="#phan-loai">Phân loại M5, M6, F7–F9 và ISO 16890</a></li>\n                    <li><a class="text-primary hover:underline" href="#ung-dung">Ứng dụng thực tế</a></li>\n                    <li><a class="text-primary hover:underline" href="#cach-chon">Cách lựa chọn và thời điểm thay</a></li>\n                    <li><a class="text-primary hover:underline" href="#faq">Câu hỏi thường gặp</a></li>\n                </ol>\n            </nav>\n\n            <p class="mb-5 leading-8"><strong>Bag Filter</strong> (Pocket Filter hay lọc túi) là một trong những dòng lọc khí phổ biến trong AHU và hệ thống HVAC. Nhờ cấu trúc nhiều túi có diện tích bề mặt lớn, bộ lọc giữ được lượng bụi cao, duy trì lưu lượng ổn định và thường được dùng làm cấp lọc trung gian để bảo vệ bộ lọc HEPA phía sau.</p>\n\n            <h2 id="bag-filter-la-gi" class="text-3xl font-bold text-secondary mt-10 mb-6">Bag Filter là gì?</h2>\n            <p class="mb-5 leading-8">Bag Filter là bộ lọc không khí gồm nhiều túi lọc được may từ vật liệu sợi tổng hợp, microfiber hoặc vật liệu chuyên dụng. Không khí đi vào miệng túi, xuyên qua lớp vật liệu; bụi và hạt ô nhiễm bị giữ lại trong khi luồng khí đã lọc tiếp tục đi qua hệ thống.</p>\n            <p class="mb-5 leading-8">So với lọc tấm phẳng, thiết kế nhiều túi tạo ra diện tích lọc lớn trong cùng một tiết diện khung. Nhờ vậy Bag Filter có khả năng chứa bụi tốt và phù hợp với lưu lượng gió lớn. Trong cấu hình nhiều cấp, vị trí điển hình là:</p>\n            <div class="bg-primary/5 border-l-4 border-primary rounded-xl p-6 my-8 text-center font-semibold leading-8">\n                Không khí ngoài trời → Pre Filter → Bag Filter → HEPA Filter → Khu vực sử dụng\n            </div>\n            <p class="mb-5 leading-8">Cách bố trí thực tế phải theo thiết kế HVAC và yêu cầu chất lượng không khí của từng khu vực. Bạn có thể đọc thêm bài <a class="text-primary font-semibold hover:underline" href="/news/hepa-filter-la-gi" onclick="openNewsDetail(\'hepa-filter-la-gi\'); return false;">HEPA Filter là gì</a> để hiểu vai trò của cấp lọc cuối.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Vì sao còn gọi là Pocket Filter?</h3>\n            <p class="mb-5 leading-8">Tên gọi <strong>Pocket Filter</strong> xuất phát từ các khoang lọc dạng túi được treo song song trong khung. Mỗi pocket vừa là bề mặt lọc vừa là khoang chứa bụi. Tùy kích thước và lưu lượng, một bộ lọc có thể có 3, 4, 5, 6, 8 hoặc 10 túi. Nhiều túi hơn thường tạo diện tích lọc lớn hơn, nhưng không có nghĩa lúc nào cũng tốt hơn: chiều rộng túi, chiều sâu túi và khoảng cách giữa các túi phải đủ để túi bung đều ở lưu lượng thiết kế.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Vai trò của Bag Filter trong AHU</h3>\n            <ul class="list-disc pl-6 space-y-3 mb-8">\n                <li>Giữ lại phần bụi mịn mà cấp lọc thô phía trước chưa loại bỏ.</li>\n                <li>Hạn chế bụi bám trên coil, quạt, ống gió và các thiết bị phía sau.</li>\n                <li>Giảm tải bụi cho HEPA Filter, từ đó kéo dài chu kỳ sử dụng của cấp lọc cuối.</li>\n                <li>Góp phần duy trì lưu lượng, chất lượng không khí và độ sạch ổn định hơn.</li>\n                <li>Tạo một cấp lọc trung gian có chi phí thay thế thấp hơn so với thay HEPA quá sớm.</li>\n            </ul>\n\n            <figure class="my-10 max-w-2xl mx-auto">\n                <img src="images/san-pham/vpm5.webp" alt="Hình ảnh thực tế Bag Filter V-PAK M5 do VAF sản xuất" width="2400" height="1792" loading="lazy" class="w-full h-auto rounded-xl shadow-lg">\n                <figcaption class="text-center text-sm text-slate-500 mt-3">Hình ảnh sản phẩm thực tế V-PAK M5 của VAF.</figcaption>\n            </figure>\n\n            <figure class="my-10 max-w-2xl mx-auto">\n                <img src="images/san-pham/vpf7.webp" alt="Bag Filter F7 V-PAK của VAF dùng trong hệ thống HVAC" width="2400" height="1792" loading="lazy" class="w-full h-auto rounded-xl shadow-lg">\n                <figcaption class="text-center text-sm text-slate-500 mt-3">Bag Filter F7 V-PAK của VAF với cấu trúc nhiều túi lọc.</figcaption>\n            </figure>\n\n            <h2 id="cau-tao" class="text-3xl font-bold text-secondary mt-10 mb-6">Cấu tạo Bag Filter</h2>\n            <div class="grid md:grid-cols-2 gap-5 my-8">\n                <div class="bg-white border rounded-xl p-5 shadow-sm"><h3 class="text-xl font-bold text-secondary mb-2">Khung lọc</h3><p>Giữ toàn bộ kết cấu, thường làm từ thép mạ kẽm, nhôm hoặc inox tùy môi trường.</p></div>\n                <div class="bg-white border rounded-xl p-5 shadow-sm"><h3 class="text-xl font-bold text-secondary mb-2">Vật liệu lọc</h3><p>Thường là sợi tổng hợp hoặc microfiber, có cấu trúc phù hợp với hiệu suất và chênh áp thiết kế.</p></div>\n                <div class="bg-white border rounded-xl p-5 shadow-sm"><h3 class="text-xl font-bold text-secondary mb-2">Các túi lọc</h3><p>Nhiều túi bố trí song song giúp tăng diện tích tiếp xúc và khả năng chứa bụi.</p></div>\n                <div class="bg-white border rounded-xl p-5 shadow-sm"><h3 class="text-xl font-bold text-secondary mb-2">Đường may, keo và gioăng</h3><p>Giữ túi ổn định, hạn chế khí đi tắt qua khe hở giữa vật liệu và khung.</p></div>\n            </div>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Nguyên lý hoạt động</h3>\n            <p class="mb-5 leading-8">Khi quạt tạo dòng khí qua bộ lọc, các hạt được giữ lại nhờ tổng hợp nhiều cơ chế như va đập quán tính, chặn bắt và khuếch tán. Bụi tích tụ dần làm chênh áp tăng. Một lớp bụi ban đầu có thể cải thiện khả năng giữ hạt, nhưng khi chênh áp vượt giới hạn thiết kế, lưu lượng giảm và quạt phải tiêu thụ nhiều năng lượng hơn.</p>\n\n            <figure class="my-10 max-w-3xl mx-auto">\n                <img src="images/anh-tin-tin/nguyen-ly-bag-filter-vaf-ai.webp" alt="Ảnh AI dựa trên sản phẩm VAF minh họa nguyên lý giữ bụi của Bag Filter sáu túi" width="1537" height="1023" loading="lazy" class="w-full h-auto rounded-xl shadow-lg">\n                <figcaption class="text-center text-sm text-slate-500 mt-3">Minh họa nguyên lý lọc dựa trên cấu tạo thực tế của Bag Filter sáu túi VAF: khí bẩn đi vào miệng túi, bụi bị giữ trong vật liệu và khí sạch đi ra phía sau.</figcaption>\n            </figure>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Chênh áp thay đổi như thế nào?</h3>\n            <p class="mb-5 leading-8">Chênh áp là độ chênh áp suất giữa phía trước và phía sau bộ lọc. Khi Bag Filter sạch, chênh áp ở mức ban đầu. Trong quá trình vận hành, bụi lấp dần các khoảng trống trong vật liệu khiến sức cản tăng. Nếu tiếp tục vận hành sau giới hạn khuyến nghị, hệ thống có thể thiếu gió, mất cân bằng áp suất phòng và tăng điện năng của quạt. Vì vậy đồng hồ chênh áp hoặc cảm biến áp suất là công cụ theo dõi đáng tin cậy hơn việc chỉ quan sát màu túi.</p>\n\n            <h2 id="phan-loai" class="text-3xl font-bold text-secondary mt-10 mb-6">Phân loại Bag Filter M5, M6, F7–F9 và ISO 16890</h2>\n            <p class="mb-5 leading-8">Theo cách gọi của EN 779:2012, các cấp lọc túi phổ biến gồm <strong>M5, M6, F7, F8 và F9</strong>. M5 và M6 thuộc nhóm lọc trung bình; F7–F9 thuộc nhóm lọc tinh. Với bộ lọc thông gió chung, <a class="text-primary font-semibold hover:underline" href="https://www.iso.org/standard/57864.html" target="_blank" rel="noopener noreferrer">ISO 16890-1:2016</a> phân nhóm bộ lọc theo hiệu suất đối với ePM1, ePM2.5, ePM10 hoặc ISO Coarse. Vì hai phương pháp đánh giá khác nhau, không nên quy đổi chỉ dựa vào tên cấp lọc; cần xem báo cáo thử nghiệm của đúng model.</p>\n            <div class="overflow-x-auto my-8">\n                <table class="w-full border-collapse text-left">\n                    <thead><tr class="bg-secondary text-white"><th class="p-4">Cấp gọi phổ biến</th><th class="p-4">Đặc điểm sử dụng</th><th class="p-4">Ứng dụng tham khảo</th></tr></thead>\n                    <tbody>\n                        <tr class="border-b"><td class="p-4 font-bold">M5</td><td class="p-4">Cấp lọc trung bình, khả năng chứa bụi lớn</td><td class="p-4">Tòa nhà, nhà xưởng, AHU thông thường</td></tr>\n                        <tr class="border-b bg-slate-50"><td class="p-4 font-bold">M6</td><td class="p-4">Hiệu suất cao hơn M5, dùng làm lọc trung gian</td><td class="p-4">Thực phẩm, linh kiện điện tử, hệ thống điều hòa</td></tr>\n                        <tr class="border-b"><td class="p-4 font-bold">F7</td><td class="p-4">Cân bằng giữa hiệu suất, khả năng chứa bụi và năng lượng</td><td class="p-4">Điện tử, thực phẩm, bệnh viện, tiền lọc HEPA</td></tr>\n                        <tr class="border-b"><td class="p-4 font-bold">F8–F9</td><td class="p-4">Hiệu suất cao hơn, cần kiểm tra chênh áp thiết kế</td><td class="p-4">Dược phẩm, phòng sạch và khu vực kiểm soát bụi nghiêm ngặt</td></tr>\n                    </tbody>\n                </table>\n            </div>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Chọn M5, M6, F7, F8 hay F9?</h3>\n            <p class="mb-5 leading-8"><strong>M5</strong> phù hợp khi ưu tiên khả năng chứa bụi và mức cản thấp ở hệ thống tiện nghi hoặc môi trường có tải bụi tương đối lớn. <strong>M6</strong> là bước nâng hiệu suất cho các AHU cần chất lượng khí tốt hơn. <strong>F7</strong> thường được lựa chọn làm cấp trung gian trước HEPA nhờ cân bằng hiệu suất và chi phí năng lượng. <strong>F8–F9</strong> phục vụ yêu cầu lọc nghiêm ngặt hơn nhưng cần kiểm tra khả năng quạt và chênh áp cho phép. Cấp lọc cuối cùng phải căn cứ vào yêu cầu đầu ra, không gian lắp và toàn bộ chuỗi lọc.</p>\n\n            <div class="grid md:grid-cols-2 gap-6 my-10 max-w-3xl mx-auto">\n                <figure><img src="images/san-pham/vpf8.webp" alt="Lọc túi Bag Filter V-PAK F8 VAF" width="2400" height="1792" loading="lazy" class="w-full h-auto rounded-xl shadow-md"><figcaption class="text-sm text-center text-slate-500 mt-2">V-PAK F8.</figcaption></figure>\n                <figure><img src="images/san-pham/vpf9.webp" alt="Lọc túi Bag Filter V-PAK F9 VAF" width="2400" height="1792" loading="lazy" class="w-full h-auto rounded-xl shadow-md"><figcaption class="text-sm text-center text-slate-500 mt-2">V-PAK F9.</figcaption></figure>\n            </div>\n\n            <h2 class="text-3xl font-bold text-secondary mt-10 mb-6">Ưu điểm và giới hạn của lọc túi</h2>\n            <div class="grid md:grid-cols-2 gap-6 my-8">\n                <div class="bg-emerald-50 border border-emerald-200 rounded-xl p-6"><h3 class="text-xl font-bold text-emerald-800 mb-3">Ưu điểm</h3><ul class="list-disc pl-6 space-y-2"><li>Diện tích lọc và khả năng chứa bụi lớn.</li><li>Nhiều lựa chọn cấp lọc, số túi và kích thước.</li><li>Giúp giảm tải và kéo dài tuổi thọ cấp HEPA.</li><li>Thay thế thuận tiện khi chọn đúng khung lắp.</li></ul></div>\n                <div class="bg-amber-50 border border-amber-200 rounded-xl p-6"><h3 class="text-xl font-bold text-amber-800 mb-3">Giới hạn</h3><ul class="list-disc pl-6 space-y-2"><li>Không thay thế HEPA trong khu vực yêu cầu độ sạch cao.</li><li>Hiệu quả giảm khi vận hành sai lưu lượng thiết kế.</li><li>Cần đủ khoảng trống để túi bung và dòng khí phân bố đều.</li><li>Phần lớn sản phẩm không phù hợp để giặt tái sử dụng.</li></ul></div>\n            </div>\n\n            <h2 id="ung-dung" class="text-3xl font-bold text-secondary mt-10 mb-6">Ứng dụng thực tế</h2>\n            <p class="mb-5 leading-8">Bag Filter được dùng trong AHU của tòa nhà thương mại, nhà máy điện tử và bán dẫn, bệnh viện, dược phẩm, thực phẩm, trung tâm dữ liệu và các dây chuyền cần kiểm soát bụi. Vai trò cụ thể có thể là lọc chính cho khu vực tiện nghi hoặc lọc trung gian trước HEPA trong hệ thống yêu cầu cao hơn.</p>\n            <div class="grid md:grid-cols-2 gap-5 my-8">\n                <div class="border rounded-xl p-5"><h3 class="text-xl font-bold text-secondary mb-2">Bệnh viện và phòng khám</h3><p>Hỗ trợ giảm tải bụi trước cấp lọc cuối tại khu điều trị, phòng xét nghiệm và các AHU phục vụ khu vực kiểm soát.</p></div>\n                <div class="border rounded-xl p-5"><h3 class="text-xl font-bold text-secondary mb-2">Điện tử và bán dẫn</h3><p>Giữ bụi mịn trước HEPA để hạn chế nguy cơ hạt ảnh hưởng tới linh kiện và quy trình chính xác.</p></div>\n                <div class="border rounded-xl p-5"><h3 class="text-xl font-bold text-secondary mb-2">Dược phẩm và thực phẩm</h3><p>Được tích hợp vào hệ thống thông gió nhằm hỗ trợ kiểm soát bụi và bảo vệ khu vực sản xuất.</p></div>\n                <div class="border rounded-xl p-5"><h3 class="text-xl font-bold text-secondary mb-2">Tòa nhà và trung tâm dữ liệu</h3><p>Cải thiện chất lượng khí cấp, hạn chế bụi bám thiết bị và duy trì điều kiện vận hành ổn định.</p></div>\n            </div>\n            <p class="mb-5 leading-8">Để tham khảo cách VAF triển khai giải pháp lọc khí trong thực tế, xem <a class="text-primary font-semibold hover:underline" href="/projects" onclick="handleNav(\'projects\'); return false;">các dự án tiêu biểu</a>.</p>\n\n            <h2 id="cach-chon" class="text-3xl font-bold text-secondary mt-10 mb-6">Cách lựa chọn Bag Filter phù hợp</h2>\n            <ol class="list-decimal pl-6 space-y-5 mb-8">\n                <li><strong>Xác định yêu cầu chất lượng không khí:</strong> chọn nhóm ISO 16890 hoặc cấp theo hồ sơ thiết kế, không chỉ dựa vào thói quen gọi F7/F8.</li>\n                <li><strong>Kiểm tra lưu lượng và vận tốc mặt:</strong> đối chiếu lưu lượng danh định của bộ lọc với AHU. Vận hành vượt thiết kế có thể tăng chênh áp và làm túi biến dạng.</li>\n                <li><strong>Đúng kích thước và số túi:</strong> đo chính xác rộng × cao × sâu; đảm bảo đủ không gian để các túi không chạm nhau hoặc chạm vỏ máy.</li>\n                <li><strong>So sánh chênh áp:</strong> xem cả chênh áp ban đầu và giới hạn thay khuyến nghị. Chênh áp thấp hơn có thể giúp giảm năng lượng quạt trong vòng đời sử dụng.</li>\n                <li><strong>Xem điều kiện môi trường:</strong> nhiệt độ, độ ẩm, hóa chất và yêu cầu vệ sinh quyết định vật liệu khung, vật liệu lọc và gioăng.</li>\n                <li><strong>Yêu cầu dữ liệu thử nghiệm:</strong> lựa chọn dựa trên tài liệu của đúng model, đúng kích thước và điều kiện thử.</li>\n            </ol>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Các kích thước và lưu lượng thường gặp</h3>\n            <p class="mb-5 leading-8">Các hệ thống có thể sử dụng kích thước như 592 × 592 mm, 592 × 490 mm hoặc 592 × 287 mm, với chiều sâu túi thay đổi theo thiết kế. Lưu lượng tham khảo thường gặp là khoảng 3.400 m³/h cho khổ đầy và 1.700 m³/h cho khổ nửa, nhưng giá trị áp dụng phải lấy từ datasheet của đúng model. Không nên chọn bộ lọc chỉ vì “lắp vừa khung” mà bỏ qua lưu lượng danh định.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Sai lầm thường gặp khi lựa chọn</h3>\n            <ul class="list-disc pl-6 space-y-3 mb-8">\n                <li>Chọn cấp lọc cao nhất nhưng không kiểm tra cột áp còn lại của quạt.</li>\n                <li>Dùng túi quá sâu trong khoang lắp ngắn khiến túi bị gập hoặc chạm vách.</li>\n                <li>Chọn quá ít túi làm diện tích lọc nhỏ và chênh áp tăng nhanh.</li>\n                <li>Không kiểm tra độ kín của khung, gioăng và cơ cấu ép lọc.</li>\n                <li>Đánh giá tình trạng lọc chỉ bằng màu sắc thay vì chênh áp và lưu lượng.</li>\n            </ul>\n\n            <div class="bg-secondary text-white rounded-2xl p-7 my-10">\n                <h3 class="text-2xl font-bold mb-3">Các dòng Bag Filter VAF</h3>\n                <p class="mb-5">Tham khảo đúng trang sản phẩm: <a class="text-cyan-300 font-bold hover:underline" href="/product/v-pakm5" onclick="openProductDetail(\'v-pakm5\'); return false;">V-PAK M5</a>, <a class="text-cyan-300 font-bold hover:underline" href="/product/v-pakm6" onclick="openProductDetail(\'v-pakm6\'); return false;">V-PAK M6</a>, <a class="text-cyan-300 font-bold hover:underline" href="/product/v-pakf7" onclick="openProductDetail(\'v-pakf7\'); return false;">V-PAK F7</a>, <a class="text-cyan-300 font-bold hover:underline" href="/product/v-pakf8" onclick="openProductDetail(\'v-pakf8\'); return false;">V-PAK F8</a> và <a class="text-cyan-300 font-bold hover:underline" href="/product/v-pakf9" onclick="openProductDetail(\'v-pakf9\'); return false;">V-PAK F9</a>.</p>\n                <a href="/contact" onclick="handleNav(\'contact\'); return false;" class="inline-block bg-primary text-white font-bold px-6 py-3 rounded-lg hover:opacity-90">Liên hệ VAF để được tư vấn</a>\n            </div>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Khi nào cần thay Bag Filter?</h3>\n            <p class="mb-5 leading-8">Không nên áp dụng một mốc thời gian cố định cho mọi hệ thống. Hãy thay khi chênh áp đạt giới hạn trong tài liệu kỹ thuật hoặc hồ sơ thiết kế; lưu lượng không còn đáp ứng; túi bị rách, ẩm, biến dạng; hoặc theo yêu cầu kiểm soát chất lượng của cơ sở. Theo dõi chênh áp giúp tránh thay quá sớm và hạn chế vận hành quá lâu gây tốn điện.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Quy trình kiểm tra và thay thế an toàn</h3>\n            <ol class="list-decimal pl-6 space-y-3 mb-8">\n                <li>Ghi nhận chênh áp, lưu lượng và tình trạng vận hành trước khi dừng AHU.</li>\n                <li>Ngắt và khóa nguồn theo quy trình an toàn của cơ sở trước khi mở khoang lọc.</li>\n                <li>Quan sát rách túi, ẩm mốc, biến dạng, bụi lọt qua và độ kín của khung.</li>\n                <li>Tháo lọc cũ nhẹ nhàng, đóng gói phù hợp để tránh phát tán bụi trong khu vực.</li>\n                <li>Vệ sinh khoang lọc, kiểm tra gioăng và lắp đúng chiều dòng khí của lọc mới.</li>\n                <li>Khởi động lại hệ thống, kiểm tra rò lọt và ghi nhận chênh áp ban đầu làm mốc theo dõi.</li>\n            </ol>\n\n            <h2 class="text-3xl font-bold text-secondary mt-10 mb-6">So sánh Bag Filter với Panel Filter và HEPA</h2>\n            <div class="overflow-x-auto my-8">\n                <table class="w-full border-collapse text-left">\n                    <thead><tr class="bg-secondary text-white"><th class="p-4">Tiêu chí</th><th class="p-4">Panel Filter</th><th class="p-4">Bag Filter</th><th class="p-4">HEPA Filter</th></tr></thead>\n                    <tbody>\n                        <tr class="border-b"><td class="p-4 font-bold">Vai trò thường gặp</td><td class="p-4">Lọc thô/tiền lọc</td><td class="p-4">Lọc trung gian</td><td class="p-4">Lọc cuối</td></tr>\n                        <tr class="border-b bg-slate-50"><td class="p-4 font-bold">Diện tích lọc</td><td class="p-4">Thấp đến trung bình</td><td class="p-4">Lớn nhờ nhiều túi</td><td class="p-4">Rất lớn nhờ vật liệu xếp nếp</td></tr>\n                        <tr class="border-b"><td class="p-4 font-bold">Khả năng chứa bụi</td><td class="p-4">Phù hợp bụi thô</td><td class="p-4">Cao</td><td class="p-4">Không nên nhận tải bụi thô lớn</td></tr>\n                        <tr class="border-b bg-slate-50"><td class="p-4 font-bold">Mục tiêu chính</td><td class="p-4">Bảo vệ cấp sau</td><td class="p-4">Giữ bụi mịn và bảo vệ HEPA</td><td class="p-4">Đạt hiệu suất lọc cuối cao</td></tr>\n                    </tbody>\n                </table>\n            </div>\n            <p class="mb-5 leading-8">Ba loại lọc không thay thế lẫn nhau mà bổ trợ trong một chuỗi lọc được thiết kế đúng. Nếu tải bụi đầu vào cao, một Pre Filter phù hợp sẽ giúp Bag Filter bền hơn; tương tự, Bag Filter được chọn đúng sẽ giảm tải đáng kể cho HEPA.</p>\n\n            <h2 class="text-3xl font-bold text-secondary mt-10 mb-6">Phân tích chi tiết từng cấp Bag Filter</h2>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Bag Filter M5</h3>\n            <p class="mb-5 leading-8">M5 là cấp đầu tiên trong nhóm lọc trung bình theo cách phân loại EN 779:2012. Dòng này thường được cân nhắc cho hệ thống điều hòa tiện nghi, nhà xưởng, khu vực có độ ẩm tương đối cao hoặc vị trí cần một bộ lọc có khả năng chứa bụi lớn nhưng sức cản ban đầu không quá cao. M5 không nhằm thay thế cấp lọc tinh hoặc HEPA. Nhiệm vụ chính là giảm tải bụi cho các thiết bị và cấp lọc phía sau.</p>\n            <p class="mb-5 leading-8">Trong một AHU có tải bụi ngoài trời lớn, M5 có thể được bố trí sau lọc thô. Tuy nhiên, hiệu quả thực tế phụ thuộc vào lưu lượng, diện tích vật liệu, số túi và tình trạng kín khít. Nếu chọn túi quá ngắn hoặc diện tích lọc nhỏ, chênh áp có thể tăng nhanh dù tên cấp lọc vẫn là M5. Vì vậy cần xem đầy đủ datasheet thay vì chỉ so sánh tên cấp.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Bag Filter M6</h3>\n            <p class="mb-5 leading-8">M6 có hiệu suất cao hơn M5 và thường được sử dụng khi hệ thống cần chất lượng khí cấp tốt hơn nhưng chưa cần chuyển ngay sang F7. Các ứng dụng tham khảo gồm hệ thống điều hòa công nghiệp, nhà máy thực phẩm, khu sản xuất linh kiện và một số AHU dùng M6 làm cấp trung gian. Khi nâng từ M5 lên M6, người thiết kế phải kiểm tra lại chênh áp và khả năng đáp ứng của quạt.</p>\n            <p class="mb-5 leading-8">Không nên hiểu M6 là lựa chọn luôn tốt hơn M5 trong mọi tình huống. Nếu mục tiêu chỉ là bảo vệ coil ở khu vực tải bụi thô cao, một cấu hình M5 có diện tích lọc lớn đôi khi phù hợp hơn về năng lượng và chu kỳ thay. Ngược lại, nếu cần giảm hạt nhỏ trước cấp sau, M6 có thể tạo giá trị rõ ràng hơn.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Bag Filter F7</h3>\n            <p class="mb-5 leading-8">F7 là một trong những cấp Bag Filter được dùng phổ biến trong các hệ thống yêu cầu kiểm soát bụi tốt. Sản phẩm thường xuất hiện ở AHU của bệnh viện, nhà máy điện tử, dược phẩm, thực phẩm và các khu vực có HEPA phía sau. Lý do F7 được lựa chọn nhiều là khả năng cân bằng giữa hiệu suất lọc, khả năng chứa bụi và mức tiêu thụ năng lượng khi bộ lọc được thiết kế đúng.</p>\n            <p class="mb-5 leading-8">Với phòng sạch, F7 chỉ là một phần của chuỗi kiểm soát ô nhiễm. Hiệu quả cuối cùng còn phụ thuộc vào cấp HEPA, độ kín hệ thống, số lần trao đổi khí, áp suất phòng, vệ sinh và quy trình vận hành. Việc ghi “F7” trên bộ lọc không đồng nghĩa toàn bộ hệ thống mặc nhiên đạt một cấp sạch cụ thể.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Bag Filter F8</h3>\n            <p class="mb-5 leading-8">F8 được dùng khi yêu cầu kiểm soát hạt nghiêm ngặt hơn F7 hoặc khi cần giảm tải bụi mịn trước HEPA. Do vật liệu và hiệu suất cao hơn, chênh áp của F8 cần được đưa vào bài toán lựa chọn quạt và năng lượng. Một bộ lọc hiệu suất cao nhưng vận hành ở lưu lượng vượt danh định có thể làm tăng sức cản, biến dạng túi và rút ngắn chu kỳ sử dụng.</p>\n            <p class="mb-5 leading-8">Trong hệ thống hiện hữu, không nên tự ý thay F7 bằng F8 chỉ vì muốn “lọc sạch hơn”. Trước khi thay đổi cần kiểm tra cột áp dự phòng, lưu lượng thiết kế, yêu cầu chất lượng không khí và giới hạn chênh áp. Nếu quạt không đủ khả năng bù sức cản, lưu lượng cấp có thể giảm và ảnh hưởng tới cân bằng áp suất của khu vực.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Bag Filter F9</h3>\n            <p class="mb-5 leading-8">F9 là cấp cao nhất trong nhóm lọc tinh của hệ phân loại EN 779 được đề cập trong bài. Dòng này có thể được xem xét cho các ứng dụng yêu cầu cao trước HEPA như dược phẩm, điện tử chính xác, bệnh viện hoặc khu nghiên cứu. Dù vậy, F9 vẫn không phải HEPA và không thể thay thế phép đánh giá hiệu suất theo tiêu chuẩn dành cho HEPA.</p>\n            <p class="mb-5 leading-8">Khi sử dụng F9, thiết kế khung lắp và gioăng càng quan trọng. Một khe hở nhỏ tạo đường bypass có thể làm giảm hiệu quả của toàn bộ cấp lọc, dù bản thân vật liệu có hiệu suất cao. Bảo trì vì thế phải kiểm tra đồng thời bề mặt túi, khung, gioăng, kẹp giữ và vách ngăn quanh bộ lọc.</p>\n\n            <h2 class="text-3xl font-bold text-secondary mt-10 mb-6">Vật liệu Bag Filter và ảnh hưởng tới vận hành</h2>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Sợi tổng hợp</h3>\n            <p class="mb-5 leading-8">Sợi tổng hợp là vật liệu phổ biến nhờ độ bền, khả năng chịu ẩm tương đối tốt và tính linh hoạt trong thiết kế. Nhà sản xuất có thể tổ chức nhiều lớp sợi với mật độ khác nhau để bụi được phân bố theo chiều sâu thay vì tập trung ngay trên bề mặt. Cấu trúc này hỗ trợ khả năng chứa bụi và giúp chênh áp tăng có kiểm soát hơn trong vòng đời sử dụng.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Microfiber và vật liệu chuyên dụng</h3>\n            <p class="mb-5 leading-8">Microfiber có kích thước sợi nhỏ hơn, tạo điều kiện tăng khả năng giữ hạt mịn. Một số ứng dụng đặc biệt có thể sử dụng vật liệu khác tùy nhiệt độ, độ ẩm hoặc hóa chất. Không nên chọn vật liệu chỉ theo hiệu suất danh nghĩa; cần xác nhận giới hạn nhiệt độ, khả năng chịu ẩm, độ bền cơ học và tính tương thích với môi trường vận hành.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">Đường may và thanh định hình</h3>\n            <p class="mb-5 leading-8">Đường may không chỉ đóng kín túi mà còn giúp kiểm soát hình dạng khi có gió. Các đường chia hoặc thanh định hình hạn chế hai mặt túi dính vào nhau, giữ khoảng cách giữa các pocket và phân bố luồng khí đều hơn. Nếu túi bị xẹp hoặc chạm nhau, một phần diện tích vật liệu không được sử dụng hiệu quả, tạo vùng vận tốc cao và làm chênh áp tăng cục bộ.</p>\n\n            <h2 class="text-3xl font-bold text-secondary mt-10 mb-6">Hiểu đúng EN 779 và ISO 16890</h2>\n            <p class="mb-5 leading-8">EN 779 từng được sử dụng rộng rãi để phân loại lọc khí thông gió thành các nhóm G, M và F. Vì tài liệu thiết kế, hồ sơ thầu và tên thương mại cũ vẫn còn phổ biến, người dùng hiện nay vẫn thường nói M5, M6, F7, F8 hoặc F9. Tuy nhiên, cách gọi này không phản ánh trực tiếp hiệu quả đối với từng nhóm bụi PM trong không khí thực tế.</p>\n            <p class="mb-5 leading-8">ISO 16890 đánh giá bộ lọc thông gió chung dựa trên khả năng loại bỏ các nhóm hạt ePM1, ePM2.5, ePM10 hoặc ISO Coarse. Cách tiếp cận theo kích thước hạt giúp người thiết kế liên hệ rõ hơn giữa bộ lọc và mục tiêu kiểm soát bụi. Ví dụ, ứng dụng quan tâm nhiều tới hạt nhỏ có thể ưu tiên xem dữ liệu ePM1; khu vực tiện nghi hoặc tải bụi lớn có thể xem đồng thời ePM2.5, ePM10 và sức cản.</p>\n            <p class="mb-5 leading-8">Không tồn tại phép quy đổi một-một hoàn toàn chính xác giữa mọi cấp EN 779 và ISO 16890. Hai bộ lọc cùng được gọi F7 có thể có kết quả ISO 16890 khác nhau do vật liệu, thiết kế và trạng thái phóng tĩnh điện. Cách làm an toàn là yêu cầu báo cáo thử nghiệm của đúng sản phẩm, đúng kích thước và đọc cả hiệu suất lẫn chênh áp.</p>\n\n            <div class="bg-slate-50 border-l-4 border-primary rounded-xl p-6 my-8">\n                <h3 class="text-xl font-bold text-secondary mb-3">Thông tin nên có trong hồ sơ lựa chọn</h3>\n                <ul class="list-disc pl-6 space-y-2">\n                    <li>Nhóm hiệu suất theo tiêu chuẩn được dự án yêu cầu.</li>\n                    <li>Kích thước khung, chiều sâu túi và số lượng túi.</li>\n                    <li>Lưu lượng danh định và vận tốc mặt tại điều kiện vận hành.</li>\n                    <li>Chênh áp ban đầu và chênh áp cuối khuyến nghị.</li>\n                    <li>Vật liệu lọc, vật liệu khung, gioăng và giới hạn nhiệt độ.</li>\n                    <li>Báo cáo thử nghiệm hoặc dữ liệu kỹ thuật của đúng model.</li>\n                </ul>\n            </div>\n\n            <h2 class="text-3xl font-bold text-secondary mt-10 mb-6">Tính toán chi phí vòng đời thay vì chỉ nhìn giá mua</h2>\n            <p class="mb-5 leading-8">Giá mua ban đầu chỉ là một phần trong tổng chi phí của Bag Filter. Trong suốt thời gian sử dụng, quạt phải thắng sức cản của bộ lọc; chênh áp càng cao và thời gian vận hành càng dài thì điện năng liên quan càng lớn. Bên cạnh đó còn có chi phí nhân công thay, dừng máy, xử lý lọc cũ và ảnh hưởng tới HEPA phía sau.</p>\n            <p class="mb-5 leading-8">Một bộ lọc có diện tích vật liệu lớn, chênh áp hợp lý và khả năng chứa bụi tốt có thể tạo chi phí vòng đời thấp hơn dù giá mua không phải thấp nhất. Để so sánh công bằng, cần đặt các lựa chọn ở cùng lưu lượng, cùng yêu cầu hiệu suất và cùng điều kiện bụi. So sánh chênh áp của hai sản phẩm ở các lưu lượng khác nhau sẽ dẫn tới kết luận sai.</p>\n            <p class="mb-5 leading-8">Cũng không nên kéo dài thời gian sử dụng chỉ để giảm số lần thay. Khi chênh áp tăng quá cao, chi phí điện và nguy cơ thiếu lưu lượng có thể lớn hơn giá trị tiết kiệm từ việc trì hoãn. Mốc thay tối ưu cần cân bằng năng lượng, chất lượng không khí, yêu cầu sản xuất và khuyến nghị kỹ thuật.</p>\n\n            <h2 class="text-3xl font-bold text-secondary mt-10 mb-6">Bảo quản và lắp đặt Bag Filter đúng cách</h2>\n            <ul class="list-disc pl-6 space-y-3 mb-8">\n                <li>Bảo quản trong bao bì sạch, khô, tránh nắng trực tiếp, nước và vật sắc nhọn làm thủng túi.</li>\n                <li>Không đặt vật nặng lên các túi vì nếp gấp sâu có thể cản trở việc bung túi khi khởi động.</li>\n                <li>Kiểm tra chiều dòng khí, kích thước và tình trạng gioăng trước khi đưa vào khung.</li>\n                <li>Đưa từng túi vào khoang cẩn thận, tránh kéo lê hoặc để túi mắc vào cạnh kim loại.</li>\n                <li>Đảm bảo các túi tách đều, không xoắn, không bị kẹp và có đủ chiều sâu để bung hết.</li>\n                <li>Ép khung kín trên toàn bộ chu vi; không dùng khe hở để “bù” sai kích thước.</li>\n                <li>Ghi ngày lắp, mã sản phẩm và chênh áp ban đầu để phục vụ theo dõi vòng đời.</li>\n            </ul>\n\n            <h2 class="text-3xl font-bold text-secondary mt-10 mb-6">Dấu hiệu Bag Filter đang vận hành không đúng</h2>\n            <p class="mb-5 leading-8"><strong>Túi rung mạnh hoặc xẹp:</strong> có thể liên quan tới lưu lượng không phù hợp, phân bố gió không đều hoặc khoảng cách túi không đủ. <strong>Chênh áp tăng rất nhanh:</strong> cần kiểm tra tải bụi, tình trạng Pre Filter, diện tích lọc và khả năng túi bung. <strong>Bụi xuất hiện phía sạch:</strong> phải kiểm tra rách vật liệu, đường may, gioăng, khung ép và hiện tượng bypass.</p>\n            <p class="mb-5 leading-8"><strong>Lưu lượng giảm nhưng chênh áp không cao:</strong> nguyên nhân có thể nằm ở quạt, damper, coil hoặc đường ống chứ không chỉ ở bộ lọc. <strong>Túi bị ướt:</strong> cần tìm nguồn ẩm, nước ngưng hoặc nước cuốn theo trước khi thay lọc mới. Nếu không xử lý nguyên nhân gốc, bộ lọc mới sẽ nhanh chóng gặp lại tình trạng tương tự.</p>\n\n            <h2 class="text-3xl font-bold text-secondary mt-10 mb-6">Thông tin cần cung cấp khi yêu cầu VAF tư vấn</h2>\n            <p class="mb-5 leading-8">Để lựa chọn nhanh và chính xác, khách hàng nên cung cấp ảnh khoang lọc hiện tại, kích thước rộng × cao × sâu, số lượng bộ lọc, lưu lượng AHU, cấp lọc hoặc nhóm ISO yêu cầu, chênh áp hiện tại, nhiệt độ, độ ẩm, đặc điểm bụi và ngành ứng dụng. Nếu thay thế một model đang dùng, ảnh nhãn sản phẩm và datasheet cũ cũng rất hữu ích.</p>\n            <p class="mb-5 leading-8">Đội ngũ kỹ thuật VAF có thể đối chiếu các thông tin này để đề xuất kích thước, số túi, vật liệu khung và cấp hiệu suất phù hợp. Việc tư vấn dựa trên dữ liệu vận hành giúp hạn chế tình trạng lọc lắp vừa nhưng sai lưu lượng, hoặc hiệu suất cao nhưng quạt không đủ cột áp.</p>\n\n            <h2 id="faq" class="text-3xl font-bold text-secondary mt-10 mb-6">Câu hỏi thường gặp</h2>\n            <div class="space-y-5">\n                <section class="border rounded-xl p-5"><h3 class="text-xl font-bold text-secondary mb-2">Bag Filter có giặt và tái sử dụng được không?</h3><p>Phần lớn Bag Filter HVAC không được thiết kế để giặt. Chỉ vệ sinh khi tài liệu của nhà sản xuất cho phép.</p></section>\n                <section class="border rounded-xl p-5"><h3 class="text-xl font-bold text-secondary mb-2">Bao lâu nên thay Bag Filter?</h3><p>Nên dựa vào chênh áp, lưu lượng, mức độ ô nhiễm và giới hạn của thiết kế thay vì chỉ dựa vào số tháng vận hành.</p></section>\n                <section class="border rounded-xl p-5"><h3 class="text-xl font-bold text-secondary mb-2">Bag Filter có thay thế HEPA Filter được không?</h3><p>Không. Bag Filter thường là cấp lọc trung gian; HEPA vẫn là cấp cuối cho khu vực yêu cầu độ sạch cao.</p></section>\n                <section class="border rounded-xl p-5"><h3 class="text-xl font-bold text-secondary mb-2">VAF có làm Bag Filter theo kích thước yêu cầu không?</h3><p>Có. VAF tư vấn kích thước, cấp lọc, số túi và vật liệu theo thông số vận hành thực tế.</p></section>\n            </div>\n\n            <h2 class="text-3xl font-bold text-secondary mt-10 mb-6">Kết luận</h2>\n            <p class="mb-5 leading-8">Bag Filter là cấp lọc quan trọng trong nhiều hệ thống HVAC nhờ diện tích bề mặt lớn, khả năng chứa bụi cao và nhiều lựa chọn hiệu suất. Để hệ thống vận hành ổn định, cần chọn đúng hiệu suất, lưu lượng, kích thước, chênh áp và điều kiện môi trường; đồng thời theo dõi chênh áp để xác định thời điểm thay phù hợp.</p>\n            <p class="text-sm text-slate-500 mt-8">Tài liệu tham khảo: <a class="text-primary hover:underline" href="https://www.iso.org/standard/57864.html" target="_blank" rel="noopener noreferrer">ISO 16890-1:2016 — Air filters for general ventilation</a>.</p>\n        '},{id:"hepa-filter-la-gi",title:"HEPA Filter Là Gì? Cấu Tạo, Nguyên Lý Hoạt Động Và Ứng Dụng",cat:"Kiến Thức",img:"images/anh-tin-tin/loc-hepa-la-gi.webp",author:"VAF Technical Team",date:"07/07/2026",desc:"HEPA Filter là bộ lọc không khí hiệu suất cao được sử dụng rộng rãi trong phòng sạch, bệnh viện, điện tử và dược phẩm. Tìm hiểu cấu tạo, nguyên lý hoạt động và ứng dụng thực tế của HEPA Filter.",content:'\n    \n                <h2 class="text-3xl font-bold text-secondary mt-10 mb-6">\nHEPA Filter là gì?\n</h2>\n\n\n<p class="mb-5 leading-8">\n<b>HEPA Filter (High Efficiency Particulate Air Filter)</b> là bộ lọc không khí hiệu suất cao được sử dụng để loại bỏ các hạt bụi mịn, vi khuẩn, bào tử nấm và các hạt aerosol khỏi dòng không khí. Đây là cấp lọc cuối (Final Filter) trong hệ thống HVAC, đóng vai trò duy trì chất lượng không khí cho phòng sạch, bệnh viện, nhà máy điện tử, dược phẩm và nhiều ngành công nghiệp yêu cầu môi trường sạch.\n</p>\n\n<p class="mb-5 leading-8">\nTheo tiêu chuẩn <b>EN1822</b>, HEPA Filter được phân loại dựa trên hiệu suất lọc tại kích thước hạt khó lọc nhất (MPPS). Các cấp lọc phổ biến hiện nay gồm <b>H13</b> và <b>H14</b>, với hiệu suất lần lượt từ <b>99.95%</b> và <b>99.995%</b>.\n</p>\n\n<div class="bg-slate-50 border-l-4 border-primary rounded-xl p-6 my-8">\n\n<h3 class="text-xl font-bold text-secondary mb-3">\nƯu điểm nổi bật của HEPA Filter\n</h3>\n\n<ul class="list-disc pl-6 space-y-2">\n\n<li>Loại bỏ hiệu quả bụi mịn PM2.5, PM1.0 và các hạt siêu mịn.</li>\n\n<li>Giữ lại vi khuẩn, bào tử nấm và các hạt mang vi sinh trong không khí.</li>\n\n<li>Duy trì cấp độ sạch theo tiêu chuẩn ISO 14644.</li>\n\n<li>Bảo vệ sản phẩm và thiết bị khỏi nguy cơ nhiễm bụi.</li>\n\n<li>Giảm tải cho hệ thống HVAC và nâng cao chất lượng không khí.</li>\n\n</ul>\n\n</div>\n\n<h2 class="text-3xl font-bold text-secondary mt-10 mb-6">\nHEPA Filter được sử dụng ở đâu?\n</h2>\n\n<img\nsrc="images/anh-tin-tin/ung-dung-cua-loc-hepa.webp"\nalt="Ứng dụng của HEPA Filter"\nclass="w-full rounded-xl shadow-lg my-8">\n\n<p class="mb-5 leading-8">\nNhờ khả năng lọc bụi hiệu suất cao, HEPA Filter được sử dụng trong nhiều lĩnh vực yêu cầu kiểm soát ô nhiễm không khí nghiêm ngặt.\n</p>\n\n<div class="grid md:grid-cols-2 gap-5 my-8">\n\n<div class="bg-white border rounded-xl p-5 shadow-sm">\n\n<h3 class="font-bold text-secondary mb-2">\n🏭 Nhà máy điện tử & bán dẫn\n</h3>\n\n<p>\nNgăn bụi ảnh hưởng đến quá trình sản xuất chip, linh kiện điện tử và màn hình.\n</p>\n\n</div>\n\n<div class="bg-white border rounded-xl p-5 shadow-sm">\n\n<h3 class="font-bold text-secondary mb-2">\n💊 Nhà máy dược phẩm\n</h3>\n\n<p>\nĐáp ứng yêu cầu GMP trong sản xuất thuốc, vaccine và thiết bị y tế.\n</p>\n\n</div>\n\n<div class="bg-white border rounded-xl p-5 shadow-sm">\n\n<h3 class="font-bold text-secondary mb-2">\n🏥 Bệnh viện\n</h3>\n\n<p>\nỨng dụng trong phòng mổ, ICU, phòng cách ly và hệ thống xử lý không khí.\n</p>\n\n</div>\n\n<div class="bg-white border rounded-xl p-5 shadow-sm">\n\n<h3 class="font-bold text-secondary mb-2">\n🍞 Thực phẩm\n</h3>\n\n<p>\nKiểm soát bụi và vi sinh trong khu vực chế biến, đóng gói thực phẩm.\n</p>\n\n</div>\n\n</div>\n\n<div class="bg-blue-50 border-l-4 border-blue-600 rounded-xl p-6 my-8">\n\n<h3 class="font-bold text-secondary mb-3">\nLưu ý từ VAF\n</h3>\n\n<p>\nHEPA Filter chỉ phát huy hiệu quả khi được lựa chọn đúng cấp lọc, lắp đặt đúng kỹ thuật và kết hợp với các cấp lọc sơ cấp (Pre Filter) và lọc tinh (Medium Filter). Việc thay thế định kỳ và kiểm tra độ kín sau lắp đặt cũng là yếu tố quan trọng để duy trì hiệu suất của toàn bộ hệ thống.\n</p>\n\n</div>\n\n<h2 class="text-3xl font-bold text-secondary mt-12 mb-6">\nCấu tạo của HEPA Filter\n</h2>\n\n<p class="mb-5 leading-8">\nMặc dù có nhiều kiểu thiết kế khác nhau, một bộ <strong>HEPA Filter</strong> tiêu chuẩn thường bao gồm 5 thành phần chính: <strong>Filter Media</strong>, <strong>Frame</strong>, <strong>Separator hoặc Mini Pleat</strong>, <strong>Sealant</strong> và <strong>Gasket</strong>. Mỗi bộ phận đều ảnh hưởng trực tiếp đến hiệu suất lọc, tuổi thọ và độ kín của bộ lọc.\n</p>\n\n<img\nsrc="images/anh-tin-tin/cau-tao-loc-hepa.webp"\nalt="Cấu tạo HEPA Filter"\nclass="w-full rounded-xl shadow-lg my-8">\n\n<div class="grid md:grid-cols-2 gap-6 my-8">\n\n<div class="border rounded-xl p-5 shadow-sm">\n<h3 class="font-bold text-secondary text-lg mb-3">\nFilter Media\n</h3>\n<p>\nLà vật liệu lọc chính, thường được chế tạo từ sợi thủy tinh siêu mịn (Micro Glass Fiber) hoặc màng PTFE cho một số ứng dụng đặc biệt.\n</p>\n</div>\n\n<div class="border rounded-xl p-5 shadow-sm">\n<h3 class="font-bold text-secondary text-lg mb-3">\nFrame\n</h3>\n<p>\nKhung bảo vệ và cố định vật liệu lọc, có thể làm bằng nhôm, thép mạ kẽm (GI), inox 304 hoặc nhựa ABS.\n</p>\n</div>\n\n<div class="border rounded-xl p-5 shadow-sm">\n<h3 class="font-bold text-secondary text-lg mb-3">\nMini Pleat\n</h3>\n<p>\nCác nếp gấp giúp tăng diện tích lọc, giảm tổn thất áp suất và kéo dài tuổi thọ của HEPA Filter.\n</p>\n</div>\n\n<div class="border rounded-xl p-5 shadow-sm">\n<h3 class="font-bold text-secondary text-lg mb-3">\nSealant & Gasket\n</h3>\n<p>\nĐảm bảo độ kín tuyệt đối giữa vật liệu lọc, khung và vị trí lắp đặt, hạn chế hiện tượng rò rỉ khí.\n</p>\n</div>\n\n</div>\n\n<h3 class="text-2xl font-bold text-secondary mt-10 mb-5">\n1. Filter Media (Vật liệu lọc)\n</h3>\n\n\n<p class="mb-5 leading-8">\nFilter Media là bộ phận quan trọng nhất của HEPA Filter. Các sợi thủy tinh siêu mịn được sắp xếp ngẫu nhiên tạo thành mạng lưới dày đặc, giúp giữ lại các hạt bụi thông qua nhiều cơ chế vật lý khác nhau.\n</p>\n\n<p class="mb-5 leading-8">\nĐể tăng diện tích lọc mà không làm tăng kích thước bộ lọc, lớp vật liệu này được gấp thành nhiều nếp nhỏ (Mini Pleat). Thiết kế này giúp tăng lưu lượng gió, giảm chênh áp và tối ưu hiệu suất vận hành.\n</p>\n\n<div class="bg-slate-50 rounded-xl p-6 my-8">\n\n<h4 class="font-bold text-secondary mb-3">\nƯu điểm của Filter Media chất lượng cao\n</h4>\n\n<ul class="list-disc pl-6 space-y-2">\n\n<li>Hiệu suất lọc cao và ổn định.</li>\n\n<li>Chênh áp ban đầu thấp.</li>\n\n<li>Tuổi thọ dài.</li>\n\n<li>Khả năng giữ bụi lớn.</li>\n\n<li>Đáp ứng tiêu chuẩn EN1822.</li>\n\n</ul>\n\n</div>\n\n<h3 class="text-2xl font-bold text-secondary mt-10 mb-5">\n2. Frame (Khung lọc)\n</h3>\n\n\n<p class="mb-5 leading-8">\nFrame giúp cố định toàn bộ kết cấu của HEPA Filter và bảo vệ vật liệu lọc trong quá trình vận chuyển, lắp đặt và vận hành. Tùy theo môi trường sử dụng, người dùng có thể lựa chọn nhiều loại vật liệu khung khác nhau.\n</p>\n\n<div class="overflow-x-auto my-8">\n\n<table class="w-full border border-gray-300 border-collapse">\n\n<thead>\n\n<tr class="bg-gray-100">\n\n<th class="border p-3">\nVật liệu khung\n</th>\n\n<th class="border p-3">\nĐặc điểm\n</th>\n\n<th class="border p-3">\nỨng dụng\n</th>\n\n</tr>\n\n</thead>\n\n<tbody>\n\n<tr>\n\n<td class="border p-3">\nNhôm định hình\n</td>\n\n<td class="border p-3">\nNhẹ, chống ăn mòn\n</td>\n\n<td class="border p-3">\nFFU, AHU, phòng sạch\n</td>\n\n</tr>\n\n<tr>\n\n<td class="border p-3">\nGI\n</td>\n\n<td class="border p-3">\nChi phí thấp\n</td>\n\n<td class="border p-3">\nHVAC công nghiệp\n</td>\n\n</tr>\n\n<tr>\n\n<td class="border p-3">\nInox 304\n</td>\n\n<td class="border p-3">\nChống ăn mòn cao\n</td>\n\n<td class="border p-3">\nDược phẩm, thực phẩm\n</td>\n\n</tr>\n\n<tr>\n\n<td class="border p-3">\nABS\n</td>\n\n<td class="border p-3">\nKhối lượng nhẹ\n</td>\n\n<td class="border p-3">\nMôi trường có hóa chất\n</td>\n\n</tr>\n\n</tbody>\n\n</table>\n\n</div>\n\n<h3 class="text-2xl font-bold text-secondary mt-10 mb-5">\n3. Mini Pleat\n</h3>\n\n<img\nsrc="images/anh-tin-tin/mini-pleat-hepa.webp"\nalt="Mini Pleat HEPA Filter"\nclass="w-full rounded-xl shadow-lg my-8">\n\n<p class="mb-5 leading-8">\nMini Pleat là công nghệ gấp nếp hiện đại được sử dụng trên hầu hết các dòng HEPA Filter cao cấp. So với kết cấu Separator truyền thống, Mini Pleat giúp tăng diện tích lọc, giảm chênh áp và cải thiện hiệu quả sử dụng năng lượng của hệ thống HVAC.\n</p>\n\n<div class="bg-blue-50 border-l-4 border-blue-600 rounded-xl p-6 my-8">\n\n<h4 class="font-bold text-secondary mb-3">\nKinh nghiệm từ VAF\n</h4>\n\n<p>\nĐối với các hệ thống HVAC vận hành liên tục, nên ưu tiên HEPA Filter sử dụng công nghệ Mini Pleat vì có tổn thất áp suất thấp hơn, giúp giảm điện năng tiêu thụ của quạt và kéo dài thời gian thay thế bộ lọc.\n</p>\n\n</div>\n\n<h2 class="text-3xl font-bold text-secondary mt-12 mb-6">\nNguyên lý hoạt động của HEPA Filter\n</h2>\n\n<p class="mb-5 leading-8">\nKhông giống như suy nghĩ phổ biến rằng HEPA Filter hoạt động như một tấm lưới với các lỗ lọc siêu nhỏ, thực tế bộ lọc giữ bụi nhờ sự kết hợp của nhiều cơ chế vật lý. Khi dòng không khí đi qua lớp <strong>Filter Media</strong>, các hạt bụi sẽ bị giữ lại thông qua quá trình va chạm, chặn bắt và khuếch tán giữa các sợi thủy tinh siêu mịn.\n</p>\n\n<img\nsrc="images/anh-tin-tin/nguyen-ly-hoat-dong-hepa.webp"\nalt="Nguyên lý hoạt động của HEPA Filter"\nclass="w-full rounded-xl shadow-lg my-8">\n\n<div class="grid md:grid-cols-2 gap-6 my-8">\n\n<div class="border rounded-xl p-5 shadow-sm">\n\n<h3 class="font-bold text-secondary text-lg mb-3">\nInterception (Chặn bắt)\n</h3>\n\n<p>\nCác hạt bụi di chuyển theo dòng khí và tiếp xúc trực tiếp với sợi lọc, sau đó bị giữ lại trên bề mặt vật liệu.\n</p>\n\n</div>\n\n<div class="border rounded-xl p-5 shadow-sm">\n\n<h3 class="font-bold text-secondary text-lg mb-3">\nInertial Impaction (Va đập quán tính)\n</h3>\n\n<p>\nCác hạt có kích thước lớn không thể thay đổi hướng theo dòng khí nên va trực tiếp vào sợi lọc và bị giữ lại.\n</p>\n\n</div>\n\n<div class="border rounded-xl p-5 shadow-sm">\n\n<h3 class="font-bold text-secondary text-lg mb-3">\nBrownian Diffusion (Khuếch tán)\n</h3>\n\n<p>\nCác hạt siêu nhỏ chuyển động ngẫu nhiên và va chạm với sợi lọc, làm tăng khả năng bị giữ lại.\n</p>\n\n</div>\n\n<div class="border rounded-xl p-5 shadow-sm">\n\n<h3 class="font-bold text-secondary text-lg mb-3">\nElectrostatic Attraction\n</h3>\n\n<p>\nMột số vật liệu lọc có thể hỗ trợ giữ lại các hạt mang điện tích, tuy nhiên đây chỉ là cơ chế bổ trợ chứ không phải yếu tố quyết định hiệu suất của HEPA Filter.\n</p>\n\n</div>\n\n</div>\n\n<div class="bg-slate-50 rounded-xl p-6 my-8">\n\n<h3 class="font-bold text-secondary text-xl mb-3">\nVì sao HEPA Filter có thể lọc được hạt rất nhỏ?\n</h3>\n\n<p>\nNhờ sự kết hợp của các cơ chế trên, HEPA Filter có khả năng giữ lại hiệu quả các hạt bụi mịn PM2.5, PM1.0, vi khuẩn, bào tử nấm và các hạt aerosol trong không khí. Hiệu suất lọc không phụ thuộc hoàn toàn vào kích thước "lỗ lọc" mà phụ thuộc vào cấu trúc của Filter Media và đặc tính chuyển động của hạt bụi.\n</p>\n\n</div>\n\n<h2 class="text-3xl font-bold text-secondary mt-12 mb-6">\nTiêu chuẩn EN1822 và các cấp lọc HEPA\n</h2>\n\n<p class="mb-5 leading-8">\nĐể đánh giá chính xác hiệu suất của HEPA Filter, tiêu chuẩn <strong>EN1822</strong> sử dụng kích thước hạt khó lọc nhất (MPPS - Most Penetrating Particle Size) thay vì chỉ dựa trên kích thước 0.3 µm như nhiều tài liệu phổ thông. Đây là tiêu chuẩn được áp dụng rộng rãi trong ngành phòng sạch và sản xuất bộ lọc không khí hiệu suất cao.\n</p>\n\n\n\n<div class="overflow-x-auto my-8">\n\n<table class="w-full border border-gray-300 border-collapse">\n\n<thead>\n\n<tr class="bg-gray-100">\n\n<th class="border p-3">\nCấp lọc\n</th>\n\n<th class="border p-3">\nHiệu suất tại MPPS\n</th>\n\n<th class="border p-3">\nỨng dụng\n</th>\n\n</tr>\n\n</thead>\n\n<tbody>\n\n<tr>\n\n<td class="border p-3 font-semibold">H13</td>\n\n<td class="border p-3">≥ 99.95%</td>\n\n<td class="border p-3">Phòng sạch ISO 7 - ISO 8, điện tử, dược phẩm</td>\n\n</tr>\n\n<tr>\n\n<td class="border p-3 font-semibold">H14</td>\n\n<td class="border p-3">≥ 99.995%</td>\n\n<td class="border p-3">Phòng mổ, bệnh viện, ISO 5 - ISO 6</td>\n\n</tr>\n\n<tr>\n\n<td class="border p-3 font-semibold">U15 - U17</td>\n\n<td class="border p-3">≥ 99.9995%</td>\n\n<td class="border p-3">Bán dẫn, vi điện tử và phòng sạch yêu cầu siêu cao</td>\n\n</tr>\n\n</tbody>\n\n</table>\n\n</div>\n\n<div class="bg-green-50 border-l-4 border-green-600 rounded-xl p-6 my-8">\n\n<h3 class="font-bold text-secondary mb-3">\nLưu ý kỹ thuật\n</h3>\n\n<p>\nHiệu suất càng cao không đồng nghĩa với việc luôn tốt hơn. Việc lựa chọn H13, H14 hay ULPA cần dựa trên cấp độ sạch yêu cầu, lưu lượng gió, tổn thất áp suất và chi phí vận hành của hệ thống HVAC. Lựa chọn đúng cấp lọc sẽ giúp tối ưu hiệu quả và kéo dài tuổi thọ của toàn bộ hệ thống.\n</p>\n\n</div>\n\n<h2 class="text-3xl font-bold text-secondary mt-12 mb-6">\nSo sánh HEPA Filter H13 và H14\n</h2>\n\n<p class="mb-5 leading-8">\nH13 và H14 là hai cấp lọc HEPA được sử dụng phổ biến nhất hiện nay. Cả hai đều đáp ứng tiêu chuẩn EN1822 nhưng được lựa chọn tùy theo yêu cầu về cấp độ sạch, mức độ kiểm soát hạt bụi và ngân sách đầu tư.\n</p>\n\n\n\n<div class="overflow-x-auto my-8">\n\n<table class="w-full border border-gray-300 border-collapse">\n\n<thead>\n\n<tr class="bg-gray-100">\n\n<th class="border p-3">Tiêu chí</th>\n<th class="border p-3">H13</th>\n<th class="border p-3">H14</th>\n\n</tr>\n\n</thead>\n\n<tbody>\n\n<tr>\n<td class="border p-3 font-semibold">Hiệu suất tại MPPS</td>\n<td class="border p-3">≥ 99.95%</td>\n<td class="border p-3">≥ 99.995%</td>\n</tr>\n\n<tr>\n<td class="border p-3 font-semibold">Ứng dụng</td>\n<td class="border p-3">Điện tử, dược phẩm, HVAC</td>\n<td class="border p-3">Bệnh viện, phòng mổ, ISO Class 5</td>\n</tr>\n\n<tr>\n<td class="border p-3 font-semibold">Tổn thất áp suất</td>\n<td class="border p-3">Thấp hơn</td>\n<td class="border p-3">Cao hơn</td>\n</tr>\n\n<tr>\n<td class="border p-3 font-semibold">Chi phí</td>\n<td class="border p-3">Tiết kiệm hơn</td>\n<td class="border p-3">Cao hơn</td>\n</tr>\n\n</tbody>\n\n</table>\n\n</div>\n\n<div class="bg-blue-50 border-l-4 border-blue-600 rounded-xl p-6 my-8">\n\n<h3 class="font-bold text-secondary mb-3">\nNên chọn H13 hay H14?\n</h3>\n\n<p>\nNếu hệ thống yêu cầu phòng sạch cho sản xuất điện tử, thực phẩm hoặc dược phẩm thông thường, H13 thường là lựa chọn phù hợp giữa hiệu suất và chi phí. Đối với phòng mổ, khu vực vô trùng hoặc các quy trình có yêu cầu kiểm soát hạt nghiêm ngặt, H14 sẽ là lựa chọn tối ưu.\n</p>\n\n</div>\n\n<h2 class="text-3xl font-bold text-secondary mt-12 mb-6">\nKhi nào cần thay HEPA Filter?\n</h2>\n\n<img\nsrc="images/anh-tin-tin/hepa-replacement.webp"\nalt="Thay thế HEPA Filter"\nclass="w-full rounded-xl shadow-lg my-8">\n\n<p class="mb-5 leading-8">\nTuổi thọ của HEPA Filter phụ thuộc vào điều kiện vận hành, chất lượng không khí đầu vào và hiệu quả của các cấp lọc sơ cấp. Thay vì chỉ dựa vào thời gian sử dụng, nên theo dõi tình trạng thực tế của bộ lọc để quyết định thời điểm thay thế.\n</p>\n\n<ul class="list-disc pl-6 space-y-2 mb-8">\n\n<li>Chênh áp vượt giới hạn thiết kế.</li>\n\n<li>Lưu lượng gió giảm đáng kể.</li>\n\n<li>Kết quả Scan Test hoặc kiểm định không đạt.</li>\n\n<li>Filter bị hư hỏng cơ học hoặc rò rỉ.</li>\n\n<li>Đến chu kỳ thay thế theo khuyến nghị của nhà sản xuất.</li>\n\n</ul>\n\n<h2 class="text-3xl font-bold text-secondary mt-12 mb-6">\nCâu hỏi thường gặp (FAQ)\n</h2>\n\n<div class="space-y-5">\n\n<div class="border rounded-xl p-5">\n<h3 class="font-bold text-secondary mb-2">HEPA Filter có lọc được virus không?</h3>\n<p>Có. HEPA Filter có khả năng giữ lại phần lớn các hạt aerosol mang virus trong không khí. Tuy nhiên, hiệu quả tổng thể còn phụ thuộc vào thiết kế hệ thống HVAC và lưu lượng gió.</p>\n</div>\n\n<div class="border rounded-xl p-5">\n<h3 class="font-bold text-secondary mb-2">HEPA Filter có vệ sinh để dùng lại được không?</h3>\n<p>Phần lớn HEPA Filter dùng trong phòng sạch là loại không thể rửa hoặc tái sử dụng. Việc vệ sinh không đúng cách có thể làm hỏng vật liệu lọc và giảm hiệu suất.</p>\n</div>\n\n<div class="border rounded-xl p-5">\n<h3 class="font-bold text-secondary mb-2">Bao lâu nên thay HEPA Filter?</h3>\n<p>Thông thường khoảng 12 tháng tùy điều kiện vận hành. Nên kết hợp theo dõi chênh áp và kết quả kiểm định để đưa ra quyết định thay thế.</p>\n</div>\n\n<div class="border rounded-xl p-5">\n<h3 class="font-bold text-secondary mb-2">HEPA H14 có luôn tốt hơn H13 không?</h3>\n<p>Không hẳn. H14 có hiệu suất cao hơn nhưng cũng có tổn thất áp suất và chi phí cao hơn. Việc lựa chọn cần phù hợp với yêu cầu của từng hệ thống.</p>\n</div>\n\n</div>\n\n<div class="bg-slate-50 rounded-xl p-8 my-10 border">\n\n<h2 class="text-2xl font-bold text-secondary mb-4">\nKết luận\n</h2>\n\n<p class="mb-5 leading-8">\nHEPA Filter là thành phần quan trọng trong hệ thống xử lý không khí, góp phần duy trì chất lượng môi trường cho phòng sạch và nhiều ngành công nghiệp yêu cầu kiểm soát ô nhiễm. Việc lựa chọn đúng cấp lọc, lắp đặt đúng kỹ thuật và bảo trì định kỳ sẽ giúp hệ thống HVAC hoạt động ổn định, tiết kiệm chi phí vận hành và đáp ứng các tiêu chuẩn quốc tế.\n</p>\n\n<p class="leading-8">\nVAF cung cấp đa dạng các dòng HEPA Filter, ULPA Filter, Medium Filter, Pre Filter và giải pháp lọc khí cho phòng sạch, bệnh viện, điện tử, dược phẩm và thực phẩm. Đội ngũ kỹ sư của chúng tôi sẵn sàng tư vấn giải pháp phù hợp với từng dự án và yêu cầu kỹ thuật cụ thể.\n</p>\n\n</div>\n\n<div class="bg-primary text-white rounded-2xl p-8 mt-12 text-center">\n\n<h2 class="text-3xl font-bold mb-4">\nCần tư vấn HEPA Filter cho dự án của bạn?\n</h2>\n\n<p class="text-lg mb-6">\nLiên hệ đội ngũ kỹ sư VAF để được tư vấn lựa chọn bộ lọc phù hợp, cung cấp tài liệu kỹ thuật và báo giá nhanh chóng.\n</p>\n\n<a href="/contact" onclick="handleNav(\'contact\'); return false;"\nclass="inline-block bg-white text-primary font-bold px-8 py-3 rounded-full hover:bg-gray-100 transition">\nLiên hệ VAF ngay\n</a>\n\n</div>\n'},{id:"huong-dan-quy-trinh-test-ro-ri-hepa-pao-dop",title:"Hướng dẫn quy trình test rò rỉ (DOP Test / PAO Test) màng lọc HEPA chuẩn xác nhất",date:"06/05/2026",cat:"Hướng dẫn",img:"images/anh-tulieu/dop-test.webp",desc:"Khám phá chi tiết 4 bước quy trình test rò rỉ màng lọc HEPA bằng phương pháp PAO/DOP chuẩn quốc tế dành cho phòng sạch dược phẩm và điện tử.",content:'\n            <p class="mb-4">Trong các hệ thống phòng sạch đạt chuẩn GMP (Dược phẩm, Điện tử, Thực phẩm, Y tế), màng lọc HEPA đóng vai trò như "lá phổi" quyết định trực tiếp đến cấp độ sạch của môi trường. Tuy nhiên, một màng lọc HEPA dù chất lượng đến đâu cũng có thể bị rò rỉ do quá trình vận chuyển, lắp đặt hoặc suy giảm tuổi thọ. Việc xuất hiện dù chỉ một lỗ thủng nhỏ cỡ sợi tóc cũng đủ để phá vỡ toàn bộ tiêu chuẩn phòng sạch, gây thiệt hại nặng nề cho sản phẩm.</p>\n            \n            <p class="mb-4">Đó là lý do quy trình <strong>kiểm tra rò rỉ (Leakage Test)</strong> bằng phương pháp DOP Test hay PAO Test là bắt buộc. Bài viết dưới đây của các kỹ sư Viet Air Filter (VAF) sẽ hướng dẫn chi tiết quy trình này.</p>\n            \n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">1. DOP Test và PAO Test màng lọc HEPA là gì?</h3>\n            <p class="mb-4">Bản chất của phương pháp này là sử dụng một hệ thống tạo ra khói nhân tạo (Aerosol) ở phía trước màng lọc (Upstream), sau đó dùng máy đo quang kế (Photometer) rà soát phía sau màng lọc (Downstream) để xem có hạt khói nào xuyên qua được hay không.</p>\n            \n            <ul class="list-disc pl-6 space-y-3 mb-6 text-slate-700">\n                <li><strong>DOP Test:</strong> Sử dụng dung môi <em>Dioctyl Phthalate</em>. Đây là phương pháp đời đầu, tạo ra kích thước hạt sương rất chuẩn (khoảng 0.3 micron). Tuy nhiên, hóa chất DOP bị Cục Bảo vệ Môi trường (EPA) đánh giá là có khả năng gây ung thư và độc hại cho kỹ sư vận hành.</li>\n                <li><strong>PAO Test:</strong> Sử dụng dung môi <em>Poly-Alpha-Olefin</em>. Đây là phương pháp thay thế hoàn hảo cho DOP hiện nay. PAO là một loại dầu tổng hợp an toàn, không độc hại, không gây ung thư, được FDA và các tiêu chuẩn phòng sạch hiện đại khuyên dùng. <em>(Ngày nay, khi nhắc đến DOP Test, các kỹ sư ngầm hiểu là đang sử dụng hóa chất PAO).</em></li>\n            </ul>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">2. Khi nào nhà máy cần tiến hành test rò rỉ PAO/DOP?</h3>\n            <p class="mb-4">Theo tiêu chuẩn ISO 14644-3 và các hướng dẫn GMP, việc test rò rỉ màng lọc HEPA (kiểm tra tính toàn vẹn) cần được thực hiện trong các trường hợp sau:</p>\n            <ul class="list-disc pl-6 space-y-3 mb-6 text-slate-700">\n                <li><strong>Lắp đặt mới:</strong> Ngay sau khi lắp đặt màng lọc HEPA vào hệ thống AHU, máy FFU, Hepa Box hoặc Passbox.</li>\n                <li><strong>Kiểm tra định kỳ:</strong> Thường là 6 tháng/lần đối với phòng sạch cấp độ cao (Class 100, Class 1000) và 12 tháng/lần với các cấp độ thấp hơn.</li>\n                <li><strong>Bảo trì, sự cố:</strong> Sau khi hệ thống bị ngưng hoạt động kéo dài, có sự cố về rung lắc mạnh, hoặc khi kết quả đo lường tiểu phân trong phòng sạch có dấu hiệu vượt mức cho phép.</li>\n            </ul>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">3. Các thiết bị cần thiết để đo kiểm PAO</h3>\n            <p class="mb-4">Để thực hiện quy trình này, đội ngũ kỹ thuật QA/QC cần trang bị 2 thiết bị cốt lõi:</p>\n            <ul class="list-disc pl-6 space-y-3 mb-6 text-slate-700">\n                <li><strong>Máy tạo khói (Aerosol Generator):</strong> Chức năng gia nhiệt và phun sương dung dịch PAO thành các hạt tiểu phân có kích thước từ 0.3 µm với mật độ cao vào dòng khí thổi tới màng lọc.</li>\n                <li><strong>Máy quang kế (Aerosol Photometer):</strong> Thiết bị có gắn đầu dò (Probe) để hút mẫu khí và phân tích quang học, từ đó đo lường nồng độ hạt khói lọt qua màng lọc với độ nhạy cực cao.</li>\n            </ul>\n            \n            <img src="images/anh-tulieu/test-loc-2.webp" class="w-full rounded-xl shadow-lg my-8" alt="Kỹ sư VAF sử dụng máy Photometer test rò rỉ màng lọc HEPA">\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">4. Chi tiết 4 bước quy trình test rò rỉ màng lọc HEPA chuẩn quốc tế</h3>\n            \n            <h4 class="text-xl font-bold text-primary mt-6 mb-3">Bước 1: Đo nồng độ hạt đầu nguồn (Upstream)</h4>\n            <p class="mb-4">Kỹ sư sẽ bơm khói PAO vào phía trước màng lọc (từ ống gió AHU hoặc ngay trên lưng máy FFU). Nồng độ hạt khói đầu nguồn tiêu chuẩn cần đạt từ <strong>10 mg/m³ đến 20 mg/m³</strong> (hoặc 10 µg/L – 100 µg/L). Thiết lập nồng độ này làm mốc chuẩn 100% trên máy Photometer.</p>\n            \n            <h4 class="text-xl font-bold text-primary mt-6 mb-3">Bước 2: Quét bề mặt màng lọc (Downstream)</h4>\n            <p class="mb-4">Kỹ sư sử dụng đầu dò của Photometer quét đều trên toàn bộ bề mặt lưới bảo vệ của màng lọc HEPA. Yêu cầu kỹ thuật cực kỳ nghiêm ngặt:</p>\n            <ul class="list-disc pl-6 space-y-3 mb-6 text-slate-700">\n                <li>Khoảng cách từ đầu dò đến bề mặt lọc: <strong>Khoảng 2.5 cm - 3.0 cm.</strong></li>\n                <li>Tốc độ quét: Chậm và đều, <strong>không vượt quá 5 cm/giây.</strong></li>\n                <li>Đường quét phải gối lên nhau một chút để đảm bảo không bỏ sót bất kỳ diện tích nào.</li>\n            </ul>\n            \n            <h4 class="text-xl font-bold text-primary mt-6 mb-3">Bước 3: Quét khu vực gioăng (Gasket) và khung</h4>\n            <p class="mb-4">Rất nhiều sự cố rò rỉ không đến từ giấy lọc màng HEPA mà đến từ điểm tiếp xúc giữa khung lọc và vỏ thiết bị (Housing), hoặc do gioăng cao su (Gasket/Gel seal) bị lão hóa, méo mó khi siết ốc. Kỹ sư phải quét kỹ các mép khung này.</p>\n            \n            <h4 class="text-xl font-bold text-primary mt-6 mb-3">Bước 4: Đánh giá kết quả và lập báo cáo</h4>\n            <p class="mb-4">Theo tiêu chuẩn quốc tế, một màng lọc HEPA H13/H14 được đánh giá là <strong>ĐẠT (PASS)</strong> khi tỷ lệ rò rỉ đo được tại bất kỳ điểm nào trên bề mặt <strong>không vượt quá 0.01%</strong> (so với nồng độ 100% đầu nguồn).</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">5. Lọc HEPA VAF - 100% Kiểm định PAO trước khi xuất xưởng</h3>\n            <p class="mb-4">Thấu hiểu sự khắt khe của hệ thống phòng sạch, <strong>Viet Air Filter (VAF)</strong> tự hào là nhà máy sản xuất thiết bị lọc khí hàng đầu tại Việt Nam áp dụng quy trình kiểm soát chất lượng chuẩn quốc tế.</p>\n            <p class="mb-4">Không giống như các sản phẩm trôi nổi không rõ nguồn gốc, 100% màng lọc HEPA (H13, H14) và ULPA do VAF sản xuất tại nhà máy Bình Dương đều được đưa vào buồng test độc lập, thực hiện <strong>quét PAO Test/ DOP Test từng tấm một</strong> trước khi đóng gói.</p>\n            <p class="mb-4">Sản phẩm khi giao đến tay khách hàng và các nhà thầu thi công luôn đi kèm đầy đủ <strong>Chứng nhận xuất xưởng (CO, CQ)</strong> và <strong>Giấy Test Report</strong> ghi rõ các thông số chênh áp, lưu lượng gió và kết quả kiểm tra tính toàn vẹn (Leak test).</p>\n            \n            <div class="bg-slate-50 p-8 rounded-2xl border-l-4 border-primary mt-10 shadow-sm">\n                <h4 class="font-bold text-xl text-secondary mb-3">Câu hỏi thường gặp (FAQ)</h4>\n                \n                <p class="font-bold text-slate-800 mt-4 mb-2">Màng lọc HEPA bị thủng có vá được không hay phải thay mới?</p>\n                <p class="text-slate-600 mb-4">Theo tiêu chuẩn IEST-RP-CC034, nếu màng lọc HEPA bị thủng, bạn có thể dùng keo Silicone chuyên dụng cho phòng sạch để vá. Tuy nhiên, tổng diện tích các vết vá <strong>không được vượt quá 5%</strong> tổng diện tích bề mặt màng lọc, và không có vết vá nào rộng quá 3.8 cm. Nếu vượt quá giới hạn này, bắt buộc phải thay màng lọc mới để đảm bảo lưu lượng và độ sạch.</p>\n                \n                <p class="font-bold text-slate-800 mt-4 mb-2">Bao lâu thì nên thay màng lọc HEPA một lần?</p>\n                <p class="text-slate-600">Tuổi thọ trung bình của lọc HEPA từ 1 - 3 năm tùy vào môi trường. Thay vì đếm thời gian, các kỹ sư bảo trì sẽ nhìn vào đồng hồ chênh áp (Magnehelic). Khi độ chênh áp qua màng lọc HEPA <strong>đạt gấp đôi (hoặc mức giới hạn) so với chênh áp ban đầu lúc mới lắp</strong>, đó là lúc lõi lọc đã nghẹt bụi và cần được thay thế ngay lập tức.</p>\n            </div>\n        '},{id:"vaf-hanh-trinh-18-nam-dinh-hinh-chuan-muc",title:"VAF – Nhà Sản Xuất Lọc Khí Tiên Phong Tại Việt Nam: Hành Trình 18 Năm Định Hình Chuẩn Mực Quốc Tế",date:"24/02/2026",cat:"Hoạt động",img:"images/anh-tulieu/Nhamayfront.webp",desc:"Khám phá hành trình 18 năm của VAF, nhà sản xuất thiết bị phòng sạch tiên phong tại Việt Nam. Tìm hiểu công nghệ tự động hóa, kiểm định EN 1822 và đối tác toàn cầu.",content:'\n            <p class="mb-4">Trong bối cảnh Việt Nam đang trở thành công xưởng sản xuất mới của thế giới, yêu cầu về độ sạch trong các nhà máy điện tử bán dẫn, dược phẩm và thực phẩm ngày càng trở nên khắt khe. Giữa sự cạnh tranh khốc liệt của các thương hiệu ngoại nhập, <strong>Công ty Cổ phần Sản xuất Lọc Khí Việt (VAF - Viet Air Filter)</strong> nổi lên như một niềm tự hào của ngành công nghiệp phụ trợ nội địa. Với 18 năm kinh nghiệm, VAF không chỉ là người tiên phong mà còn là đơn vị định hình các chuẩn mực quốc tế về khí sạch tại Việt Nam.</p>\n            \n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">1. Từ Xưởng Sản Xuất Nhỏ Đến "Cánh Chim Đầu Đàn" Ngành Lọc Khí</h3>\n            <p class="mb-4">Được thành lập vào tháng 1 năm 2008, VAF khởi đầu với một sứ mệnh táo bạo vào thời điểm đó: Xây dựng nền móng cho ngành sản xuất <strong>lọc khí công nghiệp</strong> tại Việt Nam, lĩnh vực vốn hoàn toàn phụ thuộc vào nhập khẩu.</p>\n            <p class="mb-4">Trải qua gần hai thập kỷ không ngừng nỗ lực và đổi mới, từ một xưởng sản xuất khiêm tốn với 11 nhân sự nòng cốt, VAF đã vươn mình mạnh mẽ. Ngày nay, chúng tôi sở hữu nhà máy quy mô 5.000m² tại Bình Dương, được trang bị dây chuyền tự động hóa hiện đại bậc nhất khu vực.</p>\n            \n            <img src="images/anh-tulieu/cap1.webp" class="w-full rounded-xl shadow-lg my-8" alt="Đội ngũ VAF">\n            \n            <p class="mb-4">Sự kiên định với mục tiêu chất lượng đã giúp VAF chuyển mình từ một nhà sản xuất thủ công sang mô hình nhà máy thông minh, quy tụ hơn 200 chuyên gia và kỹ sư tay nghề cao, sẵn sàng đáp ứng những đơn hàng phức tạp nhất.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">2. Giải Mã Sức Mạnh Công Nghệ: Điều Gì Làm Nên Sự Khác Biệt Của VAF?</h3>\n            <p class="mb-4">Trong ngành công nghiệp phòng sạch, "sai một ly, đi một dặm". Một hạt bụi siêu nhỏ cũng có thể làm hỏng cả một dây chuyền sản xuất chip bán dẫn triệu đô. Hiểu rõ điều này, VAF đã đầu tư mạnh mẽ vào công nghệ lõi để đảm bảo chất lượng tuyệt đối.</p>\n            \n            <h4 class="text-xl font-bold text-primary mt-6 mb-3">2.1. Tự Chủ Công Nghệ Lõi Mini-pleat Tự Động Hóa</h4>\n            <p class="mb-4">VAF tự hào là đơn vị nội địa duy nhất làm chủ hoàn toàn công nghệ sản xuất màng lọc HEPA/ULPA bằng dây chuyền <strong>Mini-pleat</strong> tự động (sử dụng công nghệ châm keo nóng Hot-melt).</p>\n            <p class="mb-4">Khác với công nghệ cũ sử dụng vách chia nhôm, công nghệ Mini-pleat giúp tạo ra các nếp gấp giấy lọc đều tăm tắp, tối ưu hóa diện tích lọc khí. Kết quả là các sản phẩm lọc VAF có độ chênh áp thấp hơn, giúp khách hàng tiết kiệm đáng kể chi phí điện năng vận hành hệ thống HVAC (Tối ưu chi phí vòng đời - LCC).</p>\n            \n            <img src="images/anh-tin-tin/daychuyenmnp.webp" class="w-full rounded-xl shadow-lg my-8" alt="Dây chuyền Mini-pleat tại VAF">\n\n            <h4 class="text-xl font-bold text-primary mt-6 mb-3">2.2. Quy Trình "Sản Xuất Sạch Để Lọc Sạch"</h4>\n            <p class="mb-4">Để tạo ra một sản phẩm dùng cho phòng sạch, bản thân quá trình sản xuất phải đảm bảo vô trùng. Tại VAF, toàn bộ quá trình lắp ráp và đóng gói các bộ lọc tinh (Fine Filter) và HEPA được thực hiện khép kín bên trong <strong>Phòng sạch Class 100.000 (ISO Class 8)</strong>. Điều này ngăn chặn triệt để nguy cơ nhiễm chéo bụi bẩn từ môi trường bên ngoài vào sản phẩm trước khi đến tay khách hàng.</p>\n\n            <h4 class="text-xl font-bold text-primary mt-6 mb-3">2.3. Vật Liệu Nhập Khẩu 100% Từ Mỹ</h4>\n            <p class="mb-4">Chất lượng của một bộ lọc nằm ở chính vật liệu lọc. VAF kiên quyết không sử dụng các loại vật liệu giá rẻ, không rõ nguồn gốc. Chúng tôi là đối tác chiến lược dài hạn, sử dụng 100% giấy lọc sợi thủy tinh cao cấp từ tập đoàn <strong>Hollingsworth & Vose (H&V - Hoa Kỳ)</strong> – nhà sản xuất vật liệu lọc hàng đầu thế giới. Điều này đảm bảo hiệu suất bắt bụi và tuổi thọ sản phẩm luôn vượt trội.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">3. Cam Kết Chất Lượng: Kiểm Định 100% Theo Chuẩn EN 1822</h3>\n            <p class="mb-4">Đây là yếu tố then chốt tạo nên uy tín của VAF. Chúng tôi không kiểm tra xác suất. <strong>100% sản phẩm lọc HEPA và ULPA</strong> trước khi xuất xưởng đều phải trải qua quy trình Scan Test (kiểm tra rò rỉ) bằng máy tạo hạt Sol khí (Aerosol) tự động.</p>\n            \n            <img src="images/anh-tin-tin/st.webp" class="w-full rounded-xl shadow-lg my-8" alt="Máy Scan Test rò rỉ tự động VAF">\n            \n            <p class="mb-4">Quy trình này tuân thủ nghiêm ngặt tiêu chuẩn quốc tế <strong>EN 1822</strong> và <strong>ISO 29463</strong>, đảm bảo rằng tấm lọc không có bất kỳ lỗ thủng nào dù là nhỏ nhất, cam kết hiệu suất lọc đúng như công bố. Ngoài ra, VAF còn đạt các chứng nhận quan trọng khác như <strong>ISO 9001:2015</strong> (Hệ thống quản lý chất lượng) và <strong>ISO 13485:2016</strong> (Tiêu chuẩn cho thiết bị y tế), khẳng định năng lực cung cấp cho lĩnh vực bệnh viện và dược phẩm.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">4. Đối Tác Tin Cậy Của Các "Ông Lớn" Toàn Cầu</h3>\n            <p class="mb-4">Với nền tảng kỹ thuật vững chắc, các giải pháp khí sạch của VAF đã vượt qua những hàng rào kỹ thuật khắt khe nhất để trở thành đối tác tin cậy của các tập đoàn đa quốc gia và các công trình trọng điểm quốc gia:</p>\n            <ul class="list-disc pl-6 space-y-3 mb-6 text-slate-700">\n                <li><strong>Công nghiệp Điện tử & Bán dẫn:</strong> Samsung, Intel, Jabil, LG Display...</li>\n                <li><strong>Thực phẩm & Đồ uống:</strong> Coca-Cola, Suntory PepsiCo, Vinamilk...</li>\n                <li><strong>Y tế & Dược phẩm:</strong> Hệ thống các bệnh viện tuyến đầu, các nhà máy dược đạt chuẩn GMP.</li>\n            </ul>\n            <p class="mb-4">Không chỉ thống lĩnh thị trường nội địa, từ năm 2020, thương hiệu VAF đã chính thức được bảo hộ bản quyền tại <strong>Hoa Kỳ</strong>, xuất khẩu thành công sang các thị trường khó tính như Mỹ, Nhật Bản và Thái Lan.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-8 mb-4">5. Tầm Nhìn 2026: Hướng Tới Sản Xuất Xanh và Bền Vững</h3>\n            <p class="mb-4">Không chỉ dừng lại ở việc cung cấp sản phẩm tốt, VAF còn ý thức sâu sắc về trách nhiệm với môi trường (ESG). Tầm nhìn đến năm 2026 của chúng tôi là chuyển đổi hoàn toàn sang mô hình <strong>Nhà Máy Thông Minh & Sản Xuất Xanh</strong>. Chúng tôi đang tiên phong phát triển dòng sản phẩm sử dụng khung nhựa ABS chuyên dụng có khả năng đốt hủy hoàn toàn sau khi sử dụng, giúp giảm thiểu rác thải công nghiệp và đồng hành cùng các đối tác đạt chứng chỉ công trình xanh (LEED/LOTUS).</p>\n\n            <div class="bg-slate-50 p-8 rounded-2xl border-l-4 border-primary mt-10 shadow-sm">\n                <h4 class="font-bold text-xl text-secondary mb-3">Bạn đang tìm kiếm giải pháp tối ưu cho hệ thống phòng sạch của mình?</h4>\n                <p class="text-slate-600 mb-4">Hãy liên hệ ngay với đội ngũ kỹ sư của VAF để được khảo sát và tư vấn kỹ thuật chuyên sâu.</p>\n                <ul class="text-slate-800 space-y-2">\n                    <li><i class="fas fa-phone-alt text-primary mr-2"></i> <strong>Hotline tư vấn:</strong> 1900 8949</li>\n                    <li><i class="fas fa-envelope text-primary mr-2"></i> <strong>Email:</strong> info@vietfil.com</li>\n                </ul>\n            </div>\n        '},{id:"cong-nghe-mini-pleat-loc-khi",title:"Công Nghệ Mini-Pleat Là Gì? Tại Sao VAF Chuyển Đổi Hoàn Toàn Sang Dây Chuyền Tự Động?",date:"20/06/2024",cat:"Công nghệ",img:"images/anh-tin-tin/mnpl.webp",desc:"Khám phá công nghệ nếp gấp siêu nhỏ giúp tăng diện tích lọc lên gấp 3 lần và lý do VAF tiên phong áp dụng tại Việt Nam.",content:'\n            <p class="mb-4">Trong ngành công nghiệp lọc khí hiện đại, công nghệ <strong>Mini-pleat (nếp gấp nhỏ)</strong> đang dần thay thế hoàn toàn công nghệ giấy nhăn (Separator) truyền thống. Tại nhà máy VAF Bình Dương, chúng tôi đã đầu tư dây chuyền nhập khẩu hoàn toàn tự động để sản xuất dòng lọc này.</p>\n            \n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">1. Công nghệ Mini-pleat là gì?</h3>\n            <p class="mb-4">Khác với lọc truyền thống dùng vách nhôm để chia nếp giấy, công nghệ Mini-pleat sử dụng các đường keo nóng (Hot melt) để định hình khoảng cách giữa các nếp giấy. Điều này giúp:</p>\n            <ul class="list-disc pl-5 space-y-2 mb-6 text-slate-700">\n                <li><strong>Tăng diện tích lọc:</strong> Cùng một kích thước khung, lọc Mini-pleat có diện tích vật liệu lọc lớn gấp 2-3 lần.</li>\n                <li><strong>Giảm chênh áp (Low Pressure Drop):</strong> Luồng khí đi qua dễ dàng hơn, giúp quạt không phải hoạt động quá tải.</li>\n                <li><strong>Tiết kiệm năng lượng:</strong> Giảm điện năng tiêu thụ cho hệ thống HVAC từ 15-20%.</li>\n            </ul>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">2. Ứng dụng tại VAF</h3>\n            <p class="mb-4">Hiện nay, các dòng sản phẩm chủ lực của VAF như <strong>Ultracel II</strong> (HEPA) và <strong>V-Dura</strong> (V-Bank) đều được sản xuất bằng công nghệ này. Đường keo đồng nhất, không bị đứt gãy giúp đảm bảo hiệu suất lọc ổn định suốt vòng đời sản phẩm.</p>\n            <img src="images/anh-tin-tin/daychuyenmnp.webp" class="w-full rounded-xl shadow-lg my-6" alt="Dây chuyền Mini-pleat tại VAF">\n        '},{id:"so-sanh-loc-hepa-h13-va-h14",title:"So Sánh Lọc HEPA H13 và H14: Khi Nào Nên Dùng Loại Nào?",date:"18/06/2024",cat:"Kiến thức",img:"images/anh-tin-tin/ssh13h14.webp",desc:"Phân biệt sự khác nhau giữa hiệu suất 99.95% và 99.995%. Hướng dẫn chọn lọc phù hợp cho Bệnh viện và Nhà máy điện tử.",content:'\n            <p class="mb-4">Rất nhiều khách hàng của VAF băn khoăn khi lựa chọn giữa hai cấp độ lọc phổ biến nhất: <strong>HEPA H13</strong> và <strong>HEPA H14</strong>. Bài viết này sẽ giúp bạn hiểu rõ sự khác biệt.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">1. Tiêu chuẩn EN 1822</h3>\n            <p class="mb-4">Theo tiêu chuẩn Châu Âu EN 1822, sự khác biệt nằm ở hiệu suất lọc hạt kích thước khó bắt nhất (MPPS):</p>\n            <table class="w-full border-collapse border border-gray-300 mb-6 text-sm">\n                <tr class="bg-gray-100"><th class="border p-2">Cấp độ</th><th class="border p-2">Hiệu suất tổng (Overall)</th><th class="border p-2">Độ lọt (Penetration)</th></tr>\n                <tr><td class="border p-2 font-bold">H13</td><td class="border p-2">≥ 99.95%</td><td class="border p-2">≤ 0.05%</td></tr>\n                <tr><td class="border p-2 font-bold">H14</td><td class="border p-2">≥ 99.995%</td><td class="border p-2">≤ 0.005%</td></tr>\n            </table>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">2. Ứng dụng thực tế</h3>\n            <ul class="list-disc pl-5 space-y-2 mb-6 text-slate-700">\n                <li><strong>Dùng H13 khi:</strong> Phòng sạch công nghiệp thông thường, phòng mổ tiểu phẫu, khu vực hành lang sạch, văn phòng cao cấp.</li>\n                <li><strong>Dùng H14 khi:</strong> Phòng mổ ghép tạng (yêu cầu vô trùng tuyệt đối), nhà máy sản xuất chip bán dẫn (Class 1 - Class 100), phòng pha chế dược phẩm, phòng an toàn sinh học cấp 3.</li>\n            </ul>\n            <p>VAF khuyến nghị khách hàng nên đo nồng độ bụi thực tế và yêu cầu chuyên gia tư vấn để tránh lãng phí chi phí đầu tư ban đầu.</p>\n        '},{id:"air-shower-buong-tam-khi-phong-sach",title:"Air Shower (Buồng Tắm Khí): Lá Chắn Đầu Tiên Của Phòng Sạch",date:"15/06/2024",cat:"Thiết bị",img:"images/anh-tin-tin/airshower.webp",desc:"Tại sao nhân viên bắt buộc phải đi qua Air Shower trước khi vào phòng sạch? Nguyên lý hoạt động và quy trình chuẩn.",content:'\n            <p class="mb-4">Con người là nguồn phát sinh bụi lớn nhất trong phòng sạch. Để loại bỏ bụi bám trên quần áo bảo hộ, <strong>Air Shower (Buồng tắm khí)</strong> là thiết bị không thể thiếu tại cửa ra vào.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">1. Nguyên lý hoạt động</h3>\n            <p class="mb-4">Khi nhân viên bước vào buồng, hệ thống cảm biến sẽ kích hoạt các vòi phun khí (Nozzle) với vận tốc cực cao (thường > 22m/s). Các luồng khí sạch được lọc qua HEPA sẽ thổi bay bụi bẩn bám trên quần áo. Bụi này sau đó được hút ngược lại qua các khe hồi gió và giữ lại ở lọc thô.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">2. Ưu điểm của Air Shower VAF</h3>\n            <ul class="list-disc pl-5 space-y-2 mb-6 text-slate-700">\n                <li><strong>Vật liệu:</strong> Inox 304 hoặc Thép sơn tĩnh điện cao cấp, chống rỉ sét.</li>\n                <li><strong>Thông minh:</strong> Hệ thống khóa liên động (Interlock) ngăn không cho hai cửa mở cùng lúc, đảm bảo áp suất phòng sạch không bị thất thoát.</li>\n                <li><strong>Tùy biến:</strong> VAF sản xuất theo kích thước yêu cầu: buồng đơn, buồng đôi, hoặc buồng đường hầm (Tunnel) cho số lượng nhân viên lớn.</li>\n            </ul>\n        '},{id:"khi-nao-can-thay-loc-khi",title:"Khi Nào Cần Thay Lọc Khí? Dấu Hiệu Nhận Biết & Quy Trình Bảo Trì",date:"10/06/2024",cat:"Hướng dẫn",img:"images/anh-tin-tin/thayloc.webp",desc:"Đừng để lọc quá hạn làm hỏng hệ thống HVAC của bạn. Hướng dẫn theo dõi chênh áp để thay thế đúng thời điểm.",content:'\n            <p class="mb-4">Một câu hỏi VAF thường xuyên nhận được: "Bao lâu thì tôi phải thay lọc?". Câu trả lời không nằm ở thời gian (3 tháng hay 6 tháng), mà nằm ở <strong>độ chênh áp</strong>.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">1. Quy tắc chênh áp (Pressure Drop)</h3>\n            <p class="mb-4">Mỗi tấm lọc đều có thông số "Chênh áp khuyến nghị thay thế" (Recommended Final Resistance). Thông thường:</p>\n            <ul class="list-disc pl-5 space-y-2 mb-6 text-slate-700">\n                <li><strong>Lọc thô (G4):</strong> Thay khi chênh áp đạt 250 Pa.</li>\n                <li><strong>Lọc túi (F7-F9):</strong> Thay khi chênh áp đạt 450 Pa.</li>\n                <li><strong>Lọc HEPA (H13-H14):</strong> Thay khi chênh áp đạt 600 Pa (hoặc gấp đôi chênh áp ban đầu).</li>\n            </ul>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">2. Rủi ro khi không thay lọc đúng hạn</h3>\n            <p class="mb-4">Nếu cố sử dụng lọc đã bị nghẹt bụi, bạn sẽ đối mặt với:</p>\n            <ul class="list-disc pl-5 space-y-2 mb-6 text-slate-700">\n                <li><strong>Tiêu tốn điện năng:</strong> Quạt phải chạy hết công suất để đẩy gió qua màng lọc bị tắc.</li>\n                <li><strong>Bục màng lọc:</strong> Áp lực gió quá lớn có thể làm rách giấy lọc, khiến bụi ồ ạt tràn vào phòng sạch (Hậu quả rất nghiêm trọng).</li>\n                <li><strong>Giảm lưu lượng gió:</strong> Phòng không đủ số lần trao đổi khí, nồng độ bụi tăng cao.</li>\n            </ul>\n        '},{id:"fan-filter-unit-ffu-phong-sach",title:"Fan Filter Unit (FFU): Giải Pháp Phòng Sạch Linh Hoạt & Tiết Kiệm",date:"05/06/2024",cat:"Công nghệ",img:"images/anh-tin-tin/FFU.webp",desc:"Tại sao FFU lại được ưa chuộng trong các nhà máy điện tử quy mô lớn? Tìm hiểu cấu tạo và lợi ích của FFU VAF.",content:'\n            <p class="mb-4">Fan Filter Unit (FFU) là thiết bị tích hợp quạt và màng lọc HEPA trong một module duy nhất, được lắp trực tiếp lên trần phòng sạch.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">1. Cấu tạo của FFU VAF</h3>\n            <ul class="list-disc pl-5 space-y-2 mb-6 text-slate-700">\n                <li><strong>Vỏ hộp:</strong> Làm bằng tôn mạ kẽm sơn tĩnh điện hoặc Inox 304, bền bỉ với môi trường.</li>\n                <li><strong>Quạt:</strong> Sử dụng động cơ AC hoặc EC (tiết kiệm điện), độ ồn thấp, tuổi thọ cao > 50.000 giờ.</li>\n                <li><strong>Màng lọc:</strong> Tích hợp HEPA H13/H14 hoặc ULPA U15 tùy yêu cầu độ sạch.</li>\n                <li><strong>Bộ điều khiển:</strong> Có thể điều chỉnh 3 cấp độ gió hoặc điều khiển trung tâm qua máy tính.</li>\n            </ul>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">2. Tại sao chọn FFU thay vì AHU trung tâm?</h3>\n            <p class="mb-4">FFU đặc biệt phù hợp cho các nhà máy điện tử lớn (như Samsung, Intel) vì tính <strong>linh hoạt</strong>. Khi cần nâng cấp độ sạch từ Class 10.000 lên Class 1.000, bạn chỉ cần lắp thêm số lượng FFU lên trần lưới (Ceiling Grid) mà không cần thay đổi toàn bộ hệ thống ống gió phức tạp.</p>\n        '},{id:"tieu-chuan-phong-sach-iso-14644-1",title:"Tiêu Chuẩn Phòng Sạch ISO 14644-1: Những Điều Cần Biết",date:"01/06/2024",cat:"Kiến thức",img:"images/anh-tin-tin/ps.webp",desc:"Tổng hợp về các cấp độ sạch ISO Class 1 đến Class 9. Làm sao để thiết kế phòng sạch đạt chuẩn?",content:'\n            <p class="mb-4">ISO 14644-1 là tiêu chuẩn quốc tế được sử dụng rộng rãi nhất để phân loại độ sạch của không khí. Tại Việt Nam, các nhà máy Dược và Điện tử đều tuân thủ tiêu chuẩn này.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">1. Các cấp độ sạch phổ biến</h3>\n            <ul class="list-disc pl-5 space-y-2 mb-6 text-slate-700">\n                <li><strong>ISO Class 5 (tương đương Class 100 cũ):</strong> Cực sạch. Ứng dụng: Phòng mổ ghép tạng, sản xuất wafer bán dẫn. Yêu cầu màng lọc ULPA hoặc HEPA phủ kín trần.</li>\n                <li><strong>ISO Class 7 (tương đương Class 10.000 cũ):</strong> Phổ biến. Ứng dụng: Phòng mổ thông thường, sản xuất thiết bị y tế, thực phẩm chức năng.</li>\n                <li><strong>ISO Class 8 (tương đương Class 100.000 cũ):</strong> Ứng dụng: Khu vực đóng gói, hành lang sạch, sản xuất bao bì dược.</li>\n            </ul>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">2. VAF hỗ trợ gì cho bạn?</h3>\n            <p class="mb-4">Để đạt được các cấp độ này, việc chọn lọc khí là yếu tố then chốt. VAF cung cấp trọn bộ giải pháp từ Lọc sơ cấp (G4) -> Lọc túi (F8) -> Lọc HEPA (H13) và thiết bị FFU để đảm bảo số lần trao đổi khí (Air Changes Per Hour - ACH) đạt yêu cầu của từng cấp độ ISO.</p>\n        '},{id:"quy-trinh-leak-test-loc-hepa",title:"Quy Trình Leak Test (Kiểm Tra Rò Rỉ) HEPA Tại Nhà Máy VAF",date:"28/05/2024",cat:"Chất lượng",img:"images/anh-tin-tin/st.webp",desc:"Mỗi tấm lọc HEPA của VAF đều được kiểm tra 100% trước khi xuất xưởng. Tìm hiểu về máy scan test tự động.",content:'\n            <p class="mb-4">Một tấm lọc HEPA dù tốt đến đâu, nếu bị rò rỉ dù chỉ một lỗ nhỏ bằng đầu kim, cũng coi như vứt đi. Đó là lý do tại VAF, quy trình <strong>Leak Test (Kiểm tra rò rỉ)</strong> là bắt buộc 100%.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">1. Phương pháp Scan Test tự động</h3>\n            <p class="mb-4">VAF sử dụng máy Scan Test tự động theo tiêu chuẩn EN 1822. Máy sẽ phun các hạt bụi sol khí (Aerosol) vào mặt trước của lọc, và đầu dò (Probe) sẽ di chuyển liên tục ở mặt sau để đo nồng độ hạt xuyên qua.</p>\n            \n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">2. Tiêu chí đạt chuẩn</h3>\n            <p class="mb-4">Nếu tại bất kỳ điểm nào trên bề mặt lọc, nồng độ hạt vượt quá mức cho phép (ví dụ > 0.01% đối với H14), máy sẽ báo lỗi và đánh dấu vị trí đó. Tấm lọc đó sẽ bị loại bỏ hoặc xử lý lại. Chỉ những tấm lọc vượt qua bài test này mới được dán tem chất lượng và đóng gói xuất xưởng.</p>\n            \n            <div class="bg-red-50 p-4 rounded border-l-4 border-primary text-slate-700 italic">\n                "Khách hàng có thể yêu cầu xem trực tiếp quy trình test tại phòng Lab của nhà máy VAF Bình Dương."\n            </div>\n        '},{id:"ap-luc-duong-ap-luc-am-phong-sach-benh-vien",title:"Vai Trò Của Áp Lực Dương & Áp Lực Âm Trong Phòng Sạch Bệnh Viện",date:"20/05/2024",cat:"Y tế",img:"images/anh-tin-tin/pal.webp",desc:"Khi nào dùng phòng áp lực dương? Khi nào dùng áp lực âm? Kiến thức quan trọng cho kỹ sư thiết kế bệnh viện.",content:'\n            <p class="mb-4">Trong thiết kế hệ thống khí sạch bệnh viện, việc kiểm soát chênh lệch áp suất là yếu tố sống còn để ngăn ngừa nhiễm khuẩn.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">1. Phòng Áp Lực Dương (Positive Pressure)</h3>\n            <p class="mb-4"><strong>Nguyên lý:</strong> Áp suất trong phòng CAO HƠN bên ngoài. Không khí chỉ đi từ trong ra ngoài.</p>\n            <p class="mb-4"><strong>Ứng dụng:</strong> Phòng mổ (Operating Theatre). Mục đích là để bảo vệ bệnh nhân đang phẫu thuật. Khi cửa mở, gió sạch từ trong phòng sẽ thổi ra, ngăn vi khuẩn từ hành lang xâm nhập vào vết mổ.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">2. Phòng Áp Lực Âm (Negative Pressure)</h3>\n            <p class="mb-4"><strong>Nguyên lý:</strong> Áp suất trong phòng THẤP HƠN bên ngoài. Không khí chỉ đi từ ngoài vào trong.</p>\n            <p class="mb-4"><strong>Ứng dụng:</strong> Phòng cách ly bệnh truyền nhiễm (như Covid-19, Lao). Mục đích là để bảo vệ cộng đồng. Không khí chứa mầm bệnh trong phòng sẽ không thể thoát ra ngoài hành lang, mà được hút qua hệ thống lọc HEPA + tia UV để xử lý trước khi thải ra môi trường.</p>\n            \n            <p>VAF cung cấp các giải pháp <strong>BIBO (Bag In Bag Out)</strong> chuyên dụng để thay thế lọc an toàn cho các phòng áp lực âm này.</p>\n        '},{id:"loc-khi-chiu-nhiet-lo-say",title:"Giải Pháp Lọc Khí Chịu Nhiệt Cho Lò Sấy Sơn Ô Tô & Thực Phẩm",date:"15/05/2024",cat:"Công nghiệp",img:"images/anh-tin-tin/u1ht.webp",desc:"Lọc khí thông thường sẽ bị chảy ở nhiệt độ cao. VAF cung cấp dòng lọc chịu nhiệt lên tới 350 độ C.",content:'\n            <p class="mb-4">Trong các dây chuyền sơn tĩnh điện ô tô hoặc sấy khô thực phẩm, nhiệt độ lò sấy có thể lên tới 250°C - 350°C. Lọc khí thông thường sử dụng keo và khung nhựa sẽ bị tan chảy ngay lập tức.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">1. Đặc tính kỹ thuật của lọc chịu nhiệt VAF</h3>\n            <ul class="list-disc pl-5 space-y-2 mb-6 text-slate-700">\n                <li><strong>Vật liệu lọc:</strong> Sợi thủy tinh (Glass fiber) đặc biệt, chịu nhiệt và không cháy.</li>\n                <li><strong>Khung:</strong> Inox 304 hoặc Thép mạ kẽm (GI) chịu lực, không biến dạng khi giãn nở nhiệt.</li>\n                <li><strong>Keo (Sealant):</strong> Sử dụng keo Ceramic hoặc Silicone đỏ chịu nhiệt độ cao.</li>\n                <li><strong>Ron (Gasket):</strong> Sợi thủy tinh bện (Fiberglass rope) đảm bảo độ kín khít.</li>\n            </ul>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">2. Các dòng sản phẩm</h3>\n            <p class="mb-4">VAF hiện cung cấp đầy đủ các dòng lọc chịu nhiệt: Lọc thô chịu nhiệt (V-HT), Lọc tinh chịu nhiệt (VMI-HT) và HEPA chịu nhiệt (Ultracel I-HT) đáp ứng mọi yêu cầu khắt khe của dây chuyền sơn VinFast, Toyota, Honda...</p>\n        '},{id:"xu-huong-phong-sach-xanh",title:"Xu Hướng 'Phòng Sạch Xanh' (Green Cleanroom) & Giải Pháp Từ VAF",date:"10/05/2024",cat:"Xu hướng",img:"images/anh-tin-tin/sxvdura.webp",desc:"Làm thế nào để vận hành phòng sạch tiết kiệm năng lượng và giảm thiểu rác thải carbon?",content:'\n            <p class="mb-4">Phòng sạch là nơi tiêu thụ năng lượng khổng lồ (gấp 10-50 lần văn phòng thông thường). Xu hướng "Phòng Sạch Xanh" đang trở thành yêu cầu bắt buộc đối với các nhà máy muốn đạt chứng chỉ LEED hoặc LOTUS.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">1. Giảm chênh áp = Giảm tiền điện</h3>\n            <p class="mb-4">VAF tập trung nghiên cứu các dòng lọc có thiết kế khí động học (V-shape) và công nghệ Mini-pleat để giảm sức cản gió xuống mức thấp nhất. Chỉ cần giảm chênh áp 50 Pa, doanh nghiệp có thể tiết kiệm hàng trăm triệu đồng tiền điện mỗi năm cho hệ thống quạt.</p>\n\n            <h3 class="text-2xl font-bold text-secondary mt-6 mb-3">2. Vật liệu thân thiện môi trường</h3>\n            <p class="mb-4">Dòng sản phẩm <strong>V-Dura (Khung nhựa ABS)</strong> của VAF là bước đột phá thay thế cho khung tôn kẽm truyền thống:</p>\n            <ul class="list-disc pl-5 space-y-2 mb-6 text-slate-700">\n                <li>Nhẹ hơn 50%, giảm chi phí vận chuyển và khí thải CO2.</li>\n                <li>Có thể đốt bỏ hoàn toàn sau khi sử dụng (Incinerable), không để lại rác thải kim loại nặng.</li>\n                <li>Bền bỉ, không bị ăn mòn trong môi trường độ ẩm cao.</li>\n            </ul>\n        '}];window.newsData=newsData;